-- ============================================================================
-- >>>> 0001_schemas_and_helpers.sql
-- ============================================================================

-- ============================================================================
-- Anvaya / Rxanvaya — Supabase migration 0001
-- Schemas, shared helper functions, updated_at / immutability triggers
-- ----------------------------------------------------------------------------
-- Purpose   : Create the `anvaya` schema for privileged (non-PostgREST-exposed)
--             helpers, and the generic trigger functions reused by later
--             migrations.
-- Depends on: nothing
-- Fresh safe: YES (all objects created IF NOT EXISTS / OR REPLACE)
-- Contract  : adds new objects only; changes no existing application contract
--
-- SECURITY NOTE
--   Supabase's PostgREST exposes the schemas listed in `pgrst.db_schemas`
--   (default: `public, graphql_public`). All data tables live in `public` so the
--   Next.js app can reach them with the anon key + RLS. Every *privileged*
--   function (hard delete, audit writer, deterministic classification,
--   correction submission) lives in `anvaya`, which is NOT exposed, so the
--   browser can never RPC into it directly.
--
-- EXTENSIONS
--   Deliberately NONE. This schema needs no pgcrypto / citext / pgvector:
--     * gen_random_uuid()  -> built in since PostgreSQL 13
--     * sha256()           -> built in since PostgreSQL 11
--   That keeps the migration runnable on a brand-new Supabase project with no
--   extension provisioning step and no superuser action.
-- ============================================================================

create schema if not exists anvaya;

comment on schema anvaya is
  'Privileged helper functions for the Anvaya pipeline. Intentionally NOT added to pgrst.db_schemas so the frontend cannot invoke these directly.';

-- ---------------------------------------------------------------------------
-- updated_at maintenance
-- ---------------------------------------------------------------------------
create or replace function public.set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

comment on function public.set_updated_at() is
  'Generic BEFORE UPDATE trigger: keeps updated_at truthful. Applied only to mutable tables.';

-- ---------------------------------------------------------------------------
-- Append-only / immutable guard
-- ---------------------------------------------------------------------------
create or replace function public.guard_immutable_row()
returns trigger
language plpgsql
as $$
declare
  v_id text;
begin
  -- In a row-level trigger NEW/OLD are composite records, not jsonb, so the
  -- record has to be converted before a field can be read by name.
  if tg_op = 'DELETE' then
    v_id := to_jsonb(old) ->> 'id';
  else
    v_id := to_jsonb(new) ->> 'id';
  end if;

  -- UPDATE is refused unconditionally: history is never rewritten.
  -- DELETE is refused too, with one narrow exception — a sanctioned erasure.
  -- anvaya.hard_delete_report() / hard_delete_patient() set this
  -- transaction-local flag, which is how a patient's right to erasure can be
  -- honoured without making these tables editable in normal operation.
  -- The flag can only be set by a SECURITY DEFINER function; a client session
  -- has no way to set another backend's GUC.
  if tg_op = 'DELETE' and current_setting('anvaya.erasure_in_progress', true) = 'on' then
    return old;
  end if;

  raise exception 'anvaya: % is append-only and cannot be % (row %)',
    tg_table_name, lower(tg_op), coalesce(v_id, '?');
end;
$$;

comment on function public.guard_immutable_row() is
  'BEFORE UPDATE OR DELETE trigger that hard-blocks mutation. Used on deterministic validation output, AI generations and audit records so no client (and no LLM write-back path) can rewrite history.';

-- ---------------------------------------------------------------------------
-- Small numeric helpers used by checks / classification
-- ---------------------------------------------------------------------------
create or replace function anvaya.num_nonnulls(variadic anyarray)
returns int
language sql
immutable
as $$
  select count(*)::int from unnest($1) as v(x) where x is not null;
$$;

comment on function anvaya.num_nonnulls(anyarray) is
  'Portable "exactly one of these FKs is set" helper for polymorphic subject columns.';

-- ============================================================================
-- >>>> 0002_enums.sql
-- ============================================================================

-- ============================================================================
-- Anvaya / Rxanvaya — Supabase migration 0002
-- Enum types
-- ----------------------------------------------------------------------------
-- Purpose   : Every closed vocabulary used by the application, defined once.
-- Depends on: 0001
-- Fresh safe: YES (guarded by pg_type lookups; PostgreSQL has no
--             "CREATE TYPE IF NOT EXISTS")
-- Contract  : Enum members are copied VERBATIM from src/lib/data.ts and
--             src/lib/i18n.tsx. Do not silently add or remove members — the
--             TypeScript unions are the existing contract.
--
--   src/lib/data.ts:7   type LangCode = "en" | "hi" | "bn"
--   src/lib/data.ts:8   type Status   = "normal" | "borderline" | "high" | "low" | "critical"
--   src/lib/i18n.tsx:16 type ReadingMode = "standard" | "simple" | "very"
--   src/lib/data.ts     conf.level: "high" | "moderate"   (only these two occur)
--   src/app/api/answer/route.ts  confidence: "high" | "moderate"
--   src/components/voice.tsx / api/answer  direction: "up" | "down" | "flat"
-- ============================================================================

do $do$
begin
  -- language -----------------------------------------------------------------
  if not exists (select 1 from pg_type where typname = 'anvaya_lang_code') then
    create type anvaya_lang_code as enum ('en', 'hi', 'bn');
  end if;

  -- deterministic result classification --------------------------------------
  -- NOTE: the task brief mentions Low/Normal/High/Critical, but the shipped
  -- application has FIVE states and renders "borderline" as "Needs attention"
  -- (src/lib/i18n.tsx "status.borderline"). The enum therefore keeps all five.
  if not exists (select 1 from pg_type where typname = 'anvaya_test_status') then
    create type anvaya_test_status as enum ('normal', 'borderline', 'high', 'low', 'critical');
  end if;

  -- reading level ------------------------------------------------------------
  if not exists (select 1 from pg_type where typname = 'anvaya_reading_level') then
    create type anvaya_reading_level as enum ('standard', 'simple', 'very');
  end if;

  -- confidence / trust -------------------------------------------------------
  if not exists (select 1 from pg_type where typname = 'anvaya_confidence_level') then
    create type anvaya_confidence_level as enum ('high', 'moderate');
  end if;

  -- trend direction ----------------------------------------------------------
  if not exists (select 1 from pg_type where typname = 'anvaya_trend_dir') then
    create type anvaya_trend_dir as enum ('up', 'down', 'flat');
  end if;

  -- roles --------------------------------------------------------------------
  if not exists (select 1 from pg_type where typname = 'anvaya_role') then
    create type anvaya_role as enum ('patient', 'doctor', 'admin');
  end if;

  if not exists (select 1 from pg_type where typname = 'anvaya_account_status') then
    create type anvaya_account_status as enum ('active', 'suspended', 'closed');
  end if;

  -- consent ------------------------------------------------------------------
  if not exists (select 1 from pg_type where typname = 'anvaya_consent_status') then
    create type anvaya_consent_status as enum ('granted', 'withdrawn', 'expired', 'declined');
  end if;

  if not exists (select 1 from pg_type where typname = 'anvaya_consent_purpose') then
    create type anvaya_consent_purpose as enum (
      'report_parsing',      -- OCR + structured extraction of the uploaded report
      'ai_explanation',      -- anonymised data sent to the LLM for plain-language text
      'rag_grounding',       -- retrieval over the guideline corpus
      'voice_interaction',   -- STT/TTS and voice Q&A
      'longitudinal_trends', -- comparing against the patient's own earlier reports
      'doctor_review'        -- sharing with a reviewing clinician
    );
  end if;

  if not exists (select 1 from pg_type where typname = 'anvaya_consent_channel') then
    create type anvaya_consent_channel as enum ('in_app', 'voice', 'clinic', 'paper', 'imported');
  end if;

  -- report lifecycle ---------------------------------------------------------
  if not exists (select 1 from pg_type where typname = 'anvaya_report_status') then
    create type anvaya_report_status as enum (
      'uploaded',        -- file received, nothing run yet
      'processing',      -- a job is running
      'extracted',       -- structured results present, awaiting patient confirmation
      'analysed',        -- validated + explained
      'in_review',       -- with a clinician
      'released',        -- doctor-signed and patient-facing
      'failed'
    );
  end if;

  if not exists (select 1 from pg_type where typname = 'anvaya_upload_channel') then
    -- src/app/upload/page.tsx offers: camera (/scan), file (PDF/JPG/PNG/CSV) and
    -- a "manual entry" sheet. "sample" is the bundled demo report.
    create type anvaya_upload_channel as enum ('camera', 'file', 'csv', 'manual', 'sample');
  end if;

  -- processing jobs ----------------------------------------------------------
  if not exists (select 1 from pg_type where typname = 'anvaya_job_status') then
    create type anvaya_job_status as enum ('queued', 'running', 'succeeded', 'failed', 'cancelled');
  end if;

  if not exists (select 1 from pg_type where typname = 'anvaya_job_stage') then
    -- Superset of the 5 friendly labels in src/lib/i18n.tsx (process.s1..s5),
    -- extended with the stages the architecture document requires.
    create type anvaya_job_stage as enum (
      'ocr',            -- process.s1 "Reading the report"
      'parsing',        -- process.s2 "Identifying your test results"
      'normalisation',  -- unit/synonym standardisation
      'validation',     -- process.s3 "Checking normal ranges"
      'anonymisation',  -- PII strip before any external call
      'rag',            -- retrieval
      'explanation',    -- process.s4 + s5 "Finding patterns" / "Preparing a simple explanation"
      'review',
      'release'
    );
  end if;

  -- provenance ---------------------------------------------------------------
  if not exists (select 1 from pg_type where typname = 'anvaya_value_source') then
    create type anvaya_value_source as enum (
      'ocr',
      'csv_import',
      'manual_entry',
      'patient_correction',
      'doctor_correction'
    );
  end if;

  if not exists (select 1 from pg_type where typname = 'anvaya_range_origin') then
    -- PIPELINE in src/lib/data.ts: "Your lab's own printed ranges are used —
    -- not generic internet numbers." So the printed range is a first-class
    -- origin alongside the curated ICMR/WHO catalogue.
    create type anvaya_range_origin as enum ('lab_printed', 'catalogue');
  end if;

  -- review workflow ----------------------------------------------------------
  if not exists (select 1 from pg_type where typname = 'anvaya_review_status') then
    create type anvaya_review_status as enum (
      'draft',
      'pending_review',
      'needs_edit',
      'approved',
      'released',
      'withdrawn'
    );
  end if;

  if not exists (select 1 from pg_type where typname = 'anvaya_version_origin') then
    create type anvaya_version_origin as enum ('ai_draft', 'doctor_edit', 'reissue');
  end if;

  if not exists (select 1 from pg_type where typname = 'anvaya_text_author') then
    create type anvaya_text_author as enum ('ai', 'doctor', 'human_editor');
  end if;

  -- AI generation ------------------------------------------------------------
  if not exists (select 1 from pg_type where typname = 'anvaya_generation_purpose') then
    create type anvaya_generation_purpose as enum (
      'test_explanation',
      'pattern_insight',
      'report_summary',
      'qa_answer',
      'translation'
    );
  end if;

  if not exists (select 1 from pg_type where typname = 'anvaya_generation_status') then
    create type anvaya_generation_status as enum ('queued', 'running', 'succeeded', 'failed', 'blocked');
  end if;

  -- Q&A ----------------------------------------------------------------------
  if not exists (select 1 from pg_type where typname = 'anvaya_message_role') then
    create type anvaya_message_role as enum ('user', 'assistant');
  end if;

  if not exists (select 1 from pg_type where typname = 'anvaya_qa_channel') then
    -- src/app/ask/page.tsx has a text input and a voice sheet.
    create type anvaya_qa_channel as enum ('text', 'voice');
  end if;

  -- storage / files ----------------------------------------------------------
  if not exists (select 1 from pg_type where typname = 'anvaya_file_kind') then
    create type anvaya_file_kind as enum (
      'original',        -- as-uploaded photo / PDF
      'processed_image', -- deskewed / contrast-fixed render
      'ocr_artifact',    -- OCR engine output blob, if retained
      'pdf_export',      -- patient or doctor PDF
      'tts_audio'        -- generated narration
    );
  end if;

  -- deletion -----------------------------------------------------------------
  if not exists (select 1 from pg_type where typname = 'anvaya_deletion_scope') then
    create type anvaya_deletion_scope as enum ('single_report', 'all_reports', 'account');
  end if;

  if not exists (select 1 from pg_type where typname = 'anvaya_deletion_status') then
    create type anvaya_deletion_status as enum ('requested', 'in_progress', 'completed', 'rejected', 'failed');
  end if;

  -- errors -------------------------------------------------------------------
  if not exists (select 1 from pg_type where typname = 'anvaya_severity') then
    create type anvaya_severity as enum ('debug', 'info', 'warning', 'error', 'critical');
  end if;

  if not exists (select 1 from pg_type where typname = 'anvaya_component') then
    create type anvaya_component as enum (
      'api', 'storage', 'ocr', 'parser', 'validator', 'anonymiser', 'rag', 'llm', 'tts', 'stt', 'database', 'other'
    );
  end if;

end
$do$;

comment on type anvaya_test_status is
  'Deterministic rule-engine output only. NEVER written by the LLM. Source of truth lives in public.validation_results; this enum is reused for denormalised display copies.';

-- ============================================================================
-- >>>> 0003_identity.sql
-- ============================================================================

-- ============================================================================
-- Anvaya / Rxanvaya — Supabase migration 0003
-- Identity: profiles, patients, doctors
-- ----------------------------------------------------------------------------
-- Purpose   : Separate the *auth-facing* row (profiles) from the two
--             role-specific records. Patient PII is confined to `patients`;
--             everything downstream that is read by the UI joins through
--             `patients` only when identity is genuinely needed.
-- Depends on: 0001 schemas/helpers, 0002 enums
-- Fresh safe: YES
-- Contract  : NEW. The current codebase has no auth at all — src/lib/data.ts
--             hardcodes a single fictional PATIENT object and there is no
--             login/middleware/session code anywhere in src/. This migration
--             introduces the identity model the architecture requires; it
--             removes nothing.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- profiles — 1:1 with auth.users
-- ---------------------------------------------------------------------------
create table if not exists public.profiles (
  id            uuid primary key,                       -- == auth.users.id
  role          anvaya_role        not null default 'patient',
  status        anvaya_account_status not null default 'active',
  full_name     text,
  email         text,
  preferred_language anvaya_lang_code not null default 'en',
  last_seen_at  timestamptz,
  created_at    timestamptz        not null default now(),
  updated_at    timestamptz        not null default now(),

  constraint profiles_email_lower_chk check (email is null or email = lower(email))
);

comment on table public.profiles is
  'One row per auth.users row. Holds ONLY routing/identity metadata — no clinical data and no PII beyond name/email needed for sign-in display.';
comment on column public.profiles.role is
  'Drives every RLS policy. patient | doctor | admin. Set by the backend/service role, never by the client.';

create unique index if not exists profiles_email_key on public.profiles (lower(email)) where email is not null;
create index if not exists profiles_role_idx on public.profiles (role) where status = 'active';

drop trigger if exists profiles_set_updated_at on public.profiles;
create trigger profiles_set_updated_at
  before update on public.profiles
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- patients — the PII record
-- ---------------------------------------------------------------------------
create table if not exists public.patients (
  id                uuid primary key default gen_random_uuid(),
  profile_id        uuid unique,                        -- nullable: clinic-entered patients may not have a login yet
  full_name         text        not null,
  name_local_script text,                               -- e.g. Devanagari rendering, mirrors data.ts PATIENT.name.hi
  date_of_birth     date,
  sex               text        check (sex is null or sex in ('female', 'male', 'other', 'unspecified')),
  phone             text,
  email             text,
  city              text,
  state             text,
  preferred_language anvaya_lang_code not null default 'en',
  -- Accessibility settings. NOTE: the shipped app keeps these in localStorage
  -- (src/lib/i18n.tsx:552-563 under LS_KEY). They are mirrored here so a
  -- returning patient keeps them across devices; the client may still treat
  -- localStorage as the fast path.
  reading_level     anvaya_reading_level not null default 'standard',
  voice_enabled     boolean     not null default true,
  high_contrast     boolean     not null default false,
  reduce_motion     boolean     not null default false,
  font_scale        smallint    not null default 0 check (font_scale between 0 and 2),
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  deleted_at        timestamptz,

  constraint patients_fk_profile foreign key (profile_id)
    references public.profiles (id) on delete set null,
  constraint patients_font_scale_chk check (font_scale >= 0 and font_scale <= 2)
);

comment on table public.patients is
  'PHI ZONE. Identifiable demographics. Never referenced by any AI/RAG table; the pipeline reaches the model only through public.anonymization_records.';
comment on column public.patients.name_local_script is
  'Backs the L2 {en, hi} name pattern in src/lib/data.ts (PATIENT.name).';

create index if not exists patients_profile_idx on public.patients (profile_id);
create index if not exists patients_active_idx on public.patients (full_name) where deleted_at is null;

drop trigger if exists patients_set_updated_at on public.patients;
create trigger patients_set_updated_at
  before update on public.patients
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- doctors
-- ---------------------------------------------------------------------------
create table if not exists public.doctors (
  id              uuid primary key default gen_random_uuid(),
  profile_id      uuid unique not null,
  full_name       text        not null,
  registration_no text,                                 -- medical council registration
  registration_body text,
  specialty       text,
  institution     text,
  verified        boolean     not null default false,
  verified_at     timestamptz,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),

  constraint doctors_fk_profile foreign key (profile_id)
    references public.profiles (id) on delete cascade
);

comment on table public.doctors is
  'Reviewer identity. Registration details are what make a sign-off attributable and auditable.';

create unique index if not exists doctors_registration_key
  on public.doctors (registration_body, registration_no)
  where registration_no is not null;

drop trigger if exists doctors_set_updated_at on public.doctors;
create trigger doctors_set_updated_at
  before update on public.doctors
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- Keep profiles in sync with auth.users
-- ---------------------------------------------------------------------------
create or replace function public.handle_new_auth_user()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  insert into public.profiles (id, role, full_name, email)
  values (
    new.id,
    coalesce(nullif(new.raw_user_meta_data ->> 'role', ''), 'patient')::anvaya_role,
    new.raw_user_meta_data ->> 'full_name',
    new.email
  )
  on conflict (id) do nothing;
  return new;
end;
$$;

comment on function public.handle_new_auth_user() is
  'Creates the profile row on signup. SECURITY DEFINER so it can write profiles despite the no-client-INSERT policy. Role is taken from server-set user metadata, never from client-controlled input.';

-- Installed only when auth.users exists (always true on Supabase; skipped in
-- bare-Postgres test harnesses) so the file stays runnable in both.
do $do$
begin
  if to_regclass('auth.users') is not null then
    drop trigger if exists on_auth_user_created on auth.users;
    create trigger on_auth_user_created
      after insert on auth.users
      for each row execute function public.handle_new_auth_user();
  end if;
end
$do$;

-- ============================================================================
-- >>>> 0004_doctor_access.sql
-- ============================================================================

-- ============================================================================
-- Anvaya / Rxanvaya — Supabase migration 0004
-- Doctor ↔ patient authorisation grants
-- ----------------------------------------------------------------------------
-- Purpose   : A clinician may only see reports for patients they have been
--             explicitly granted. This table is the single predicate behind
--             every doctor-facing RLS policy, so "cannot arbitrarily access
--             unrelated patients" is enforced in the database rather than in
--             application code.
-- Depends on: 0003
-- Fresh safe: YES
-- Contract  : NEW. The current app has no doctor login at all — /doctor is a
--             patient-facing printable summary (src/app/doctor/page.tsx renders
--             "A clinician-style view to share with your doctor"). Introducing a
--             real reviewer identity does not change that page's contract.
-- ============================================================================

create table if not exists public.doctor_patient_access (
  id          uuid primary key default gen_random_uuid(),
  doctor_id   uuid not null,
  patient_id  uuid not null,
  status      text not null default 'active'
              check (status in ('active', 'revoked')),
  reason      text,                                     -- why access was granted (audit narrative)
  granted_by  uuid,                                     -- profiles.id of whoever authorised it
  granted_at  timestamptz not null default now(),
  expires_at  timestamptz,
  revoked_at  timestamptz,
  revoked_by  uuid,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),

  constraint dpa_fk_doctor  foreign key (doctor_id)  references public.doctors (id) on delete cascade,
  constraint dpa_fk_patient foreign key (patient_id) references public.patients (id) on delete cascade,
  constraint dpa_fk_granted_by foreign key (granted_by) references public.profiles (id) on delete set null,
  constraint dpa_revoked_consistency check (
    (status <> 'revoked') or (revoked_at is not null)
  ),
  constraint dpa_expiry_after_grant check (expires_at is null or expires_at > granted_at)
);

comment on table public.doctor_patient_access is
  'Time-boxed reviewer authorisation. Access is deny-by-default: no row, no visibility.';

-- One ACTIVE grant per (doctor, patient); history of revoked grants is kept.
create unique index if not exists dpa_one_active_per_pair
  on public.doctor_patient_access (doctor_id, patient_id)
  where status = 'active';

create index if not exists dpa_patient_idx on public.doctor_patient_access (patient_id, status);
create index if not exists dpa_doctor_active_idx on public.doctor_patient_access (doctor_id) where status = 'active';

drop trigger if exists dpa_set_updated_at on public.doctor_patient_access;
create trigger dpa_set_updated_at
  before update on public.doctor_patient_access
  for each row execute function public.set_updated_at();

-- ============================================================================
-- >>>> 0005_consent.sql
-- ============================================================================

-- ============================================================================
-- Anvaya / Rxanvaya — Supabase migration 0005
-- Consent: policy catalogue + patient consent records
-- ----------------------------------------------------------------------------
-- Purpose   : Auditable, purpose-scoped, versioned consent. A boolean
--             consent=true is NOT sufficient: the record must say which policy
--             text was shown, for what purpose, when, via what channel, and
--             when it was withdrawn.
-- Depends on: 0002, 0003
-- Fresh safe: YES
-- Contract  : NEW. The shipped app has no consent UI and no consent storage —
--             src/app/settings/page.tsx has language/reading-mode/font/voice/
--             contrast/motion controls only, and the only privacy text is
--             src/app/how/page.tsx:117-120 ("Reports can be deleted after
--             processing"). This table is what turns that claim into a record.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- consent_policies — the versioned text a patient actually agreed to
-- ---------------------------------------------------------------------------
create table if not exists public.consent_policies (
  id             uuid primary key default gen_random_uuid(),
  code           text        not null,                  -- stable policy family, e.g. 'anvaya_processing'
  version        text        not null,                  -- e.g. '1.0.0'
  purpose        anvaya_consent_purpose not null,
  title_en       text        not null,
  title_hi       text,
  summary_en     text        not null,
  summary_hi     text,
  full_text_en   text        not null,
  full_text_hi   text,
  doc_hash       text        not null,                  -- sha256 of the canonical text shown
  effective_from timestamptz not null default now(),
  effective_to   timestamptz,
  is_active      boolean     not null default true,

  constraint consent_policies_version_key unique (code, version, purpose),
  constraint consent_policies_window_chk check (effective_to is null or effective_to > effective_from)
);

comment on table public.consent_policies is
  'Immutable catalogue of consent texts. Versioning here is what lets an old consent remain valid under the policy that was current when it was given.';
comment on column public.consent_policies.doc_hash is
  'sha256 of the exact text rendered to the patient. Makes "what did they actually agree to?" answerable years later.';

-- Exactly one active version per (code, purpose).
create unique index if not exists consent_policies_one_active
  on public.consent_policies (code, purpose)
  where is_active;

create index if not exists consent_policies_purpose_idx on public.consent_policies (purpose) where is_active;

-- ---------------------------------------------------------------------------
-- patient_consents — one row per decision (append-oriented)
-- ---------------------------------------------------------------------------
create table if not exists public.patient_consents (
  id            uuid primary key default gen_random_uuid(),
  patient_id    uuid not null,
  policy_id     uuid not null,
  purpose       anvaya_consent_purpose not null,
  status        anvaya_consent_status not null,
  channel       anvaya_consent_channel not null default 'in_app',
  granted_at    timestamptz not null default now(),
  expires_at    timestamptz,
  revoked_at    timestamptz,
  revoked_by    uuid,
  revocation_reason text,
  -- Evidence bundle: ip, user agent, UI version, STT transcript reference for
  -- voice consent. Deliberately jsonb (free-form evidence) — the *queryable*
  -- facts (who/what/when) are proper columns above.
  evidence      jsonb not null default '{}'::jsonb,
  ip_address    inet,
  user_agent    text,
  created_at    timestamptz not null default now(),

  constraint consents_fk_patient foreign key (patient_id) references public.patients (id) on delete restrict,
  constraint consents_fk_policy  foreign key (policy_id)  references public.consent_policies (id) on delete restrict,
  constraint consents_fk_revoked_by foreign key (revoked_by) references public.profiles (id) on delete set null,
  -- A consent can only be "revoked" with a timestamp, and only if it was granted.
  constraint consents_revoked_needs_ts check (status <> 'withdrawn' or revoked_at is not null),
  constraint consents_declined_not_granted check (status <> 'declined' or revoked_at is null)
);

comment on table public.patient_consents is
  'Append-oriented consent ledger. A withdrawal is a NEW row (status withdrawn, with revoked_at), never a delete or an edit, so the original grant stays provable.';
comment on constraint consents_fk_patient on public.patient_consents is
  'ON DELETE RESTRICT, deliberately not CASCADE. A patient row must never silently take the consent ledger with it: erasure goes through anvaya.hard_delete_patient(), which deletes consents explicitly inside a sanctioned-erasure window and keeps an audit record that it did so. RESTRICT also avoids a confusing failure mode — because row triggers fire before FK enforcement, a CASCADE here would surface the append-only error instead of the referential one.';
comment on column public.patient_consents.purpose is
  'Denormalised from consent_policies.purpose so the common "is purpose X consented right now?" query is a single indexed lookup.';

-- NOTE: deliberately NO unique index on (patient_id, purpose) WHERE status =
-- 'granted'. Because this table is append-only (the immutable trigger below
-- forbids flipping an old row to 'withdrawn'), a patient who withdraws and later
-- re-consents would legitimately hold two 'granted' rows. Authority is therefore
-- "the most recent row for this purpose wins" — implemented in
-- anvaya.has_active_consent() (0017). A unique index here would make lawful
-- re-consent impossible.
create index if not exists consents_active_lookup_idx
  on public.patient_consents (patient_id, purpose, granted_at desc);

create index if not exists consents_patient_idx on public.patient_consents (patient_id, granted_at desc);
create index if not exists consents_policy_idx on public.patient_consents (policy_id);

-- Append-only: no UPDATE, no DELETE. Corrections are new rows.
drop trigger if exists consents_immutable on public.patient_consents;
create trigger consents_immutable
  before update or delete on public.patient_consents
  for each row execute function public.guard_immutable_row();

-- ============================================================================
-- >>>> 0006_lab_catalog.sql
-- ============================================================================

-- ============================================================================
-- Anvaya / Rxanvaya — Supabase migration 0006
-- Laboratory catalogue: test definitions, aliases, reference ranges, rules
-- ----------------------------------------------------------------------------
-- Purpose   : Normalise test identity and make reference ranges versioned and
--             demographically scoped, so a historical report can be re-explained
--             against the range that was in force on its collection date.
-- Depends on: 0001, 0002
-- Fresh safe: YES
-- Contract  : NEW tables, but the *codes and ranges are taken verbatim* from
--             the TestDef records in src/lib/data.ts (14 tests) so the existing
--             UI identifiers (test ids used as route params at /test/[id]) keep
--             working unchanged.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- lab_test_catalog
-- ---------------------------------------------------------------------------
create table if not exists public.lab_test_catalog (
  id           uuid primary key default gen_random_uuid(),
  code         text        not null,                    -- 'hemoglobin', 'hba1c', ... == TestDef.id in src/lib/data.ts
  name_en      text        not null,
  name_hi      text,
  simple_name_en text,                                  -- TestDef.simple.en ("Bad cholesterol")
  simple_name_hi text,
  default_unit text,                                    -- TestDef.unit
  loinc_code   text,
  category     text,                                    -- 'haematology' | 'lipid' | 'glycaemia' | 'renal' | 'electrolyte'
  description_medical text,                             -- TestDef.what.med
  description_plain_en text,                            -- TestDef.what.en
  description_plain_hi text,
  description_very_simple_en text,                      -- TestDef.what.vs_en
  description_very_simple_hi text,
  icon_key     text,                                    -- TestDef.icon (lucide name) — UI hint, no clinical meaning
  sort_order   int         not null default 0,
  is_active    boolean     not null default true,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),

  constraint lab_test_code_key unique (code)
);

comment on table public.lab_test_catalog is
  'Canonical test identity. `code` is the same string the frontend already uses (TESTS keys / /test/[id] route param), so no client identifier changes.';
comment on column public.lab_test_catalog.icon_key is
  'Purely a rendering hint (TestIcon in src/components/core.tsx). Never used in any clinical decision.';

-- Case-insensitive lookup without needing the citext extension.
create unique index if not exists lab_test_code_lower_key on public.lab_test_catalog (lower(code));
create index if not exists lab_test_category_idx on public.lab_test_catalog (category) where is_active;

drop trigger if exists lab_test_set_updated_at on public.lab_test_catalog;
create trigger lab_test_set_updated_at
  before update on public.lab_test_catalog
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- lab_test_aliases — the normalisation dictionary
-- ---------------------------------------------------------------------------
create table if not exists public.lab_test_aliases (
  id           uuid primary key default gen_random_uuid(),
  lab_test_id  uuid not null,
  alias        text not null,                           -- 'Hb', 'Haemoglobin', 'हीमोग्लोबिन', 'GLU'
  language     anvaya_lang_code not null default 'en',
  source       text not null default 'manual'
               check (source in ('manual', 'ocr_observed', 'lab_dictionary', 'loinc')),
  created_at   timestamptz not null default now(),

  constraint aliases_fk_test foreign key (lab_test_id) references public.lab_test_catalog (id) on delete cascade
);

comment on table public.lab_test_aliases is
  'Synonym dictionary behind the "Data normalisation" pipeline stage (src/lib/data.ts PIPELINE: test names, synonyms and units are standardised — e.g. "Hb", "Haemoglobin", "हेमोग्लोबिन").';

create unique index if not exists aliases_unique on public.lab_test_aliases (lab_test_id, lower(alias), language);
create index if not exists aliases_lookup_idx on public.lab_test_aliases (lower(alias));

-- ---------------------------------------------------------------------------
-- reference_range_sources
-- ---------------------------------------------------------------------------
create table if not exists public.reference_range_sources (
  id           uuid primary key default gen_random_uuid(),
  code         text not null unique,                    -- 'ICMR' | 'WHO' | 'AHA' | 'CDC' | 'MEDLINEPLUS' | 'LAB'
  name         text not null,
  country      text,
  url          text,
  authority_rank smallint not null default 100
               check (authority_rank > 0),              -- 1 = most authoritative; used to pick between candidate ranges
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

comment on table public.reference_range_sources is
  'Who published a reference range. ICMR/WHO carry the lowest authority_rank so they win ties, matching the architecture requirement to prefer Indian/ICMR/WHO ranges.';

drop trigger if exists rrs_set_updated_at on public.reference_range_sources;
create trigger rrs_set_updated_at
  before update on public.reference_range_sources
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- reference_ranges — versioned, demographically scoped
-- ---------------------------------------------------------------------------
create table if not exists public.reference_ranges (
  id             uuid primary key default gen_random_uuid(),
  lab_test_id    uuid not null,
  source_id      uuid not null,
  unit           text not null,                         -- a range is meaningless without its unit
  ref_low        numeric(14,5),
  ref_high       numeric(14,5),
  critical_low   numeric(14,5),                         -- panic value, where the source defines one
  critical_high  numeric(14,5),
  -- Width of the "borderline" band, as a fraction beyond the ref bound.
  -- The shipped UI has a 5th status ("borderline" / "Needs attention") that a
  -- plain low/high comparison cannot produce, so the band is explicit config
  -- rather than a magic number buried in code.
  borderline_frac numeric(6,4) not null default 0
               check (borderline_frac >= 0 and borderline_frac < 1),
  applicable_sex text check (applicable_sex is null or applicable_sex in ('female', 'male', 'any')),
  age_min_years  smallint check (age_min_years is null or age_min_years >= 0),
  age_max_years  smallint check (age_max_years is null or age_max_years <= 150),
  population     text,                                  -- e.g. 'adult', 'paediatric', 'pregnancy', 'indian_adult'
  version        text not null,
  effective_from date not null,
  effective_to   date,                                  -- NULL = current
  is_active      boolean not null default true,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),

  constraint rr_fk_test   foreign key (lab_test_id) references public.lab_test_catalog (id) on delete restrict,
  constraint rr_fk_source foreign key (source_id)   references public.reference_range_sources (id) on delete restrict,
  -- At least one bound must exist, otherwise the range cannot classify anything.
  constraint rr_needs_a_bound check (ref_low is not null or ref_high is not null),
  constraint rr_low_lt_high check (ref_low is null or ref_high is null or ref_low < ref_high),
  constraint rr_critical_low_below check (critical_low is null or ref_low is null or critical_low < ref_low),
  constraint rr_critical_high_above check (critical_high is null or ref_high is null or critical_high > ref_high),
  constraint rr_age_window check (age_min_years is null or age_max_years is null or age_min_years <= age_max_years),
  constraint rr_window check (effective_to is null or effective_to >= effective_from)
);

comment on table public.reference_ranges is
  'Versioned, effective-dated reference ranges. Rows are never edited in place to change a bound: a new version row is inserted and the old row gets effective_to set, so any past validation stays reproducible.';
comment on column public.reference_ranges.effective_to is
  'NULL means "currently in force". A validation row pins the exact range id it used, so setting effective_to does not rewrite history.';

create unique index if not exists rr_version_key
  on public.reference_ranges (lab_test_id, source_id, version, unit,
                              coalesce(applicable_sex, 'any'),
                              coalesce(population, 'all'),
                              effective_from);

-- Fast "which range applies to this test/sex/age today?" lookup.
create index if not exists rr_applicability_idx
  on public.reference_ranges (lab_test_id, effective_from desc)
  where is_active;

create index if not exists rr_source_idx on public.reference_ranges (source_id);
create index if not exists rr_effective_idx on public.reference_ranges (effective_from, effective_to);

drop trigger if exists rr_set_updated_at on public.reference_ranges;
create trigger rr_set_updated_at
  before update on public.reference_ranges
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- clinical_rules — versioned validation rule definitions
-- ---------------------------------------------------------------------------
create table if not exists public.clinical_rules (
  id             uuid primary key default gen_random_uuid(),
  rule_key       text not null,                         -- e.g. 'range_threshold_v1'
  version        text not null,
  description    text not null,
  engine_version text not null,                         -- deterministic engine build id
  params         jsonb not null default '{}'::jsonb,    -- non-secret rule parameters (band widths, rounding mode)
  applies_to     uuid,                                  -- optional: restrict to one lab_test_catalog row
  effective_from timestamptz not null default now(),
  effective_to   timestamptz,
  is_active      boolean not null default true,
  created_at     timestamptz not null default now(),

  constraint rules_fk_test foreign key (applies_to) references public.lab_test_catalog (id) on delete cascade,
  constraint rules_window check (effective_to is null or effective_to > effective_from)
);

-- NOTE: this must be a unique INDEX, not a table-level UNIQUE constraint —
-- PostgreSQL does not permit expressions (here, coalesce) inside a UNIQUE
-- constraint, only inside an index.
create unique index if not exists rules_version_key
  on public.clinical_rules (rule_key, version,
                            coalesce(applies_to, '00000000-0000-0000-0000-000000000000'::uuid));

comment on table public.clinical_rules is
  'Rule catalogue. A validation row records the rule id + version that produced it, so re-running the engine later yields the identical classification.';
comment on column public.clinical_rules.params is
  'Rule tuning parameters ONLY. Never store credentials, API keys or secrets in this or any other table — those belong in Supabase Vault / environment variables.';

create index if not exists rules_active_idx on public.clinical_rules (rule_key, effective_from desc) where is_active;
create index if not exists rules_test_idx on public.clinical_rules (applies_to) where applies_to is not null;

-- ============================================================================
-- >>>> 0007_reports.sql
-- ============================================================================

-- ============================================================================
-- Anvaya / Rxanvaya — Supabase migration 0007
-- Reports: lab_reports, report_files, report_processing_jobs, ocr_results
-- ----------------------------------------------------------------------------
-- Purpose   : The upload side of UPLOAD -> OCR/PARSING -> ... -> PATIENT.
--             Files themselves live in Supabase Storage; these tables hold
--             metadata and the storage key.
-- Depends on: 0002, 0003
-- Fresh safe: YES
-- Contract  : Maps onto the Report interface in src/lib/data.ts:710-723
--               { id, date:L2, month:L2, testsCount, attention, entries[] }
--             and the four demo reports feb26/apr26/jun26/aug26.
--             `legacy_code` preserves those string ids so /compare?old=apr26&new=aug26
--             (src/app/compare/page.tsx:51-52) keeps resolving.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- lab_reports
-- ---------------------------------------------------------------------------
create table if not exists public.lab_reports (
  id             uuid primary key default gen_random_uuid(),
  patient_id     uuid not null,
  legacy_code    text,                                  -- 'feb26' | 'apr26' | ... existing app identifiers
  status         anvaya_report_status not null default 'uploaded',
  upload_channel anvaya_upload_channel not null default 'file',
  lab_name       text,
  lab_location   text,
  report_number  text,                                  -- the lab's own accession/report no
  collected_on   date not null,                         -- the clinical date that drives trends
  received_at    timestamptz not null default now(),
  -- Printed-on-report header fields captured by OCR; kept OUTSIDE the
  -- anonymised payload that is sent to the LLM.
  reported_test_count smallint,
  report_language anvaya_lang_code not null default 'en',
  notes          text,
  created_by     uuid,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  deleted_at     timestamptz,
  deleted_by     uuid,
  deletion_request_id uuid,

  constraint reports_fk_patient foreign key (patient_id) references public.patients (id) on delete restrict,
  constraint reports_fk_created_by foreign key (created_by) references public.profiles (id) on delete set null,
  constraint reports_not_future check (collected_on <= current_date + 1),
  constraint reports_test_count_chk check (reported_test_count is null or reported_test_count >= 0)
);

comment on table public.lab_reports is
  'One row per uploaded laboratory report. Soft-deleted (deleted_at) rather than removed; erasure happens only through anvaya.hard_delete_report() so the act is auditable.';
comment on column public.lab_reports.patient_id is
  'ON DELETE RESTRICT by design: deleting a patient row must never silently cascade away medical records. Account erasure is an explicit, audited function call.';
comment on column public.lab_reports.legacy_code is
  'Compatibility shim for the hardcoded report ids in src/lib/data.ts (feb26/apr26/jun26/aug26) used by the /compare route.';

create unique index if not exists reports_legacy_code_key
  on public.lab_reports (legacy_code) where legacy_code is not null;

-- Patient history: the single hottest query in the app (My Reports / Trends).
create index if not exists reports_patient_history_idx
  on public.lab_reports (patient_id, collected_on desc)
  where deleted_at is null;

create index if not exists reports_status_idx on public.lab_reports (status) where deleted_at is null;
create index if not exists reports_collected_idx on public.lab_reports (collected_on desc);
create index if not exists reports_pending_review_idx on public.lab_reports (status, created_at)
  where deleted_at is null and status in ('analysed', 'in_review');

drop trigger if exists reports_set_updated_at on public.lab_reports;
create trigger reports_set_updated_at
  before update on public.lab_reports
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- report_files — storage references (never the bytes themselves)
-- ---------------------------------------------------------------------------
create table if not exists public.report_files (
  id            uuid primary key default gen_random_uuid(),
  report_id     uuid not null,
  kind          anvaya_file_kind not null,
  bucket        text not null,                          -- storage bucket id, e.g. 'report-originals'
  storage_path  text not null,                          -- object key inside the bucket
  mime_type     text,
  byte_size     bigint check (byte_size is null or byte_size >= 0),
  checksum_sha256 text,
  page_count    smallint check (page_count is null or page_count > 0),
  language      anvaya_lang_code,
  is_current    boolean not null default true,
  created_at    timestamptz not null default now(),

  constraint files_fk_report foreign key (report_id) references public.lab_reports (id) on delete restrict,
  constraint files_bucket_key unique (bucket, storage_path)
);

comment on table public.report_files is
  'Pointers into Supabase Storage. Buckets holding medical data are PRIVATE; access goes through signed URLs so storage ACLs and database RLS agree.';
comment on column public.report_files.storage_path is
  'Convention: {patient_id}/{report_id}/{kind}-{n}.{ext}. Prefixing with patient_id makes per-patient erasure a single prefix delete.';

create index if not exists files_report_idx on public.report_files (report_id, kind) where is_current;

-- ---------------------------------------------------------------------------
-- report_processing_jobs
-- ---------------------------------------------------------------------------
create table if not exists public.report_processing_jobs (
  id             uuid primary key default gen_random_uuid(),
  report_id      uuid not null,
  stage          anvaya_job_stage not null default 'ocr',
  status         anvaya_job_status not null default 'queued',
  attempt        smallint not null default 1 check (attempt > 0),
  progress_pct   smallint not null default 0 check (progress_pct between 0 and 100),
  idempotency_key text,
  input_ref      text,                                  -- storage path the job consumes
  output_ref     text,
  error_code     text,
  error_message  text,
  retry_of       uuid,
  started_at     timestamptz,
  finished_at    timestamptz,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),

  constraint jobs_fk_report foreign key (report_id) references public.lab_reports (id) on delete cascade,
  constraint jobs_fk_retry_of foreign key (retry_of) references public.report_processing_jobs (id) on delete set null,
  constraint jobs_finished_after_start check (finished_at is null or started_at is null or finished_at >= started_at),
  constraint jobs_terminal_needs_finish check (
    status not in ('succeeded', 'failed', 'cancelled') or finished_at is not null
  )
);

comment on table public.report_processing_jobs is
  'One row per pipeline stage execution. The UI progress screen (src/app/processing/page.tsx, 5 friendly labels) reads a projection of these rows; the enum is the fuller architecture stage set.';
comment on column public.report_processing_jobs.idempotency_key is
  'Lets a retrying worker re-submit safely without double-processing a report.';

create unique index if not exists jobs_idempotency_key
  on public.report_processing_jobs (idempotency_key) where idempotency_key is not null;

-- Worker queue drain: "give me the oldest queued job for this stage".
create index if not exists jobs_queue_idx
  on public.report_processing_jobs (stage, created_at)
  where status = 'queued';

create index if not exists jobs_report_idx on public.report_processing_jobs (report_id, stage, attempt);
create index if not exists jobs_running_idx on public.report_processing_jobs (status, started_at) where status = 'running';
create index if not exists jobs_failed_idx on public.report_processing_jobs (finished_at desc) where status = 'failed';

drop trigger if exists jobs_set_updated_at on public.report_processing_jobs;
create trigger jobs_set_updated_at
  before update on public.report_processing_jobs
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- ocr_results
-- ---------------------------------------------------------------------------
create table if not exists public.ocr_results (
  id            uuid primary key default gen_random_uuid(),
  report_id     uuid not null,
  job_id        uuid,
  page_no       smallint not null default 1 check (page_no > 0),
  engine        text not null,                          -- 'vision-model-x', 'tesseract', ...
  engine_version text,
  -- Raw OCR text is retained because it is the provenance for every parsed
  -- value. It CAN contain the patient name printed on the report, so this table
  -- is in the PHI zone and is never read by the LLM path.
  raw_text      text,
  layout        jsonb,                                  -- boxes/lines for highlight-in-source UI
  confidence    numeric(5,4) check (confidence is null or (confidence >= 0 and confidence <= 1)),
  word_count    int check (word_count is null or word_count >= 0),
  status        anvaya_job_status not null default 'succeeded',
  artifact_path text,                                   -- optional storage key for a full OCR dump
  created_at    timestamptz not null default now(),

  constraint ocr_fk_report foreign key (report_id) references public.lab_reports (id) on delete cascade,
  constraint ocr_fk_job    foreign key (job_id)    references public.report_processing_jobs (id) on delete set null
);

comment on table public.ocr_results is
  'PHI ZONE. Verbatim OCR output. Provenance for parsed values; explicitly excluded from anything sent to an external model.';

create unique index if not exists ocr_page_key on public.ocr_results (report_id, page_no, engine);
create index if not exists ocr_job_idx on public.ocr_results (job_id) where job_id is not null;

-- ============================================================================
-- >>>> 0008_test_results.sql
-- ============================================================================

-- ============================================================================
-- Anvaya / Rxanvaya — Supabase migration 0008
-- test_results — parsed / structured laboratory results
-- ----------------------------------------------------------------------------
-- Purpose   : One row per (report, test). Holds the parsed value, its unit, the
--             reference range printed on the report, OCR confidence and the
--             correction history. Holds NO classification of its own: the
--             deterministic status lives in validation_results (migration 0009).
-- Depends on: 0006, 0007
-- Fresh safe: YES
-- Contract  : Mirrors the extracted schema in the architecture doc and the
--             ReportEntry interface (src/lib/data.ts:704-708):
--               { test_name, value, unit, ref_low, ref_high, status }
--             `test`  -> lab_test_id (normalised)
--             `value` -> value / original_value
--             `status`-> resolved through validation_results, NOT stored here
--
-- WHY STATUS IS NOT A COLUMN HERE
--   src/lib/data.ts hardcodes `status` per entry, but those values are not
--   reproducible from (value, ref_low, ref_high): triglycerides 205 mg/dL is
--   marked "borderline" while 170 mg/dL is "high" against ref_high 150, and
--   glucose 126 mg/dL is "borderline" against ref 70-99. No single deterministic
--   rule over the demo data reproduces them. Treating status as *rule output
--   that is persisted* (0009) instead of a stored display column is what makes
--   classification reproducible and un-editable by the LLM.
-- ============================================================================

create table if not exists public.test_results (
  id              uuid primary key default gen_random_uuid(),
  report_id       uuid not null,
  lab_test_id     uuid,                                 -- NULL only when the parser could not map the name
  ocr_result_id   uuid,
  job_id          uuid,
  sort_index      smallint not null default 0,

  -- what the document literally said (provenance) -----------------------------
  raw_name        text not null,                        -- exactly as printed, e.g. "Hb"
  raw_unit        text,
  raw_value_text  text,                                 -- "10.5", "<0.5", "Trace"
  value_qualifier text check (value_qualifier is null or value_qualifier in ('<', '>', '<=', '>=', '~', '+', 'negative', 'positive', 'trace')),

  -- parsed, unit-normalised value -------------------------------------------
  value           numeric(14,5),
  unit            text,
  is_quantitative boolean not null default true,
  qualitative_value text,                               -- for non-numeric results ("Negative")

  -- reference range printed on THIS report ----------------------------------
  printed_ref_low  numeric(14,5),
  printed_ref_high numeric(14,5),
  printed_ref_text text,                                -- TestDef.ref.text, e.g. "12–16 g/dL"
  reference_range_id uuid,                              -- catalogue range, when one matched

  -- parser confidence --------------------------------------------------------
  ocr_confidence  numeric(5,4) check (ocr_confidence is null or (ocr_confidence >= 0 and ocr_confidence <= 1)),
  field_confidence jsonb not null default '{}'::jsonb,  -- per-field: {name:0.99,value:0.91,unit:0.95}
  confidence_level anvaya_confidence_level,             -- TestDef.conf.level
  confidence_note_en text,                              -- TestDef.conf.note.en
  confidence_note_hi text,

  -- correction audit trail ---------------------------------------------------
  value_source    anvaya_value_source not null default 'ocr',
  original_value  numeric(14,5),                        -- immutable: what the parser first produced
  corrected_value numeric(14,5),
  corrected_by    uuid,
  corrected_at    timestamptz,
  correction_reason text,

  -- pointer to the authoritative deterministic verdict -----------------------
  current_validation_id uuid,                           -- FK added in 0009 (circular, deferred)

  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),

  constraint tr_fk_report  foreign key (report_id)   references public.lab_reports (id) on delete restrict,
  constraint tr_fk_test    foreign key (lab_test_id) references public.lab_test_catalog (id) on delete restrict,
  constraint tr_fk_ocr     foreign key (ocr_result_id) references public.ocr_results (id) on delete set null,
  constraint tr_fk_job     foreign key (job_id)      references public.report_processing_jobs (id) on delete set null,
  constraint tr_fk_corrected_by foreign key (corrected_by) references public.profiles (id) on delete set null,
  -- a numeric result must have a value; a qualitative one must have text
  constraint tr_value_shape check (
    (is_quantitative and value is not null) or
    (not is_quantitative and qualitative_value is not null)
  ),
  -- a correction requires the audit fields that justify it
  constraint tr_correction_audit check (
    corrected_value is null or (corrected_by is not null and corrected_at is not null)
  ),
  constraint tr_printed_range_chk check (
    printed_ref_low is null or printed_ref_high is null or printed_ref_low < printed_ref_high
  ),
  constraint tr_source_matches_correction check (
    (value_source not in ('patient_correction', 'doctor_correction')) or corrected_value is not null
  )
);

comment on table public.test_results is
  'Structured laboratory results — the STRUCTURED TESTS stage output. The effective value is coalesce(corrected_value, value).';
comment on column public.test_results.printed_ref_text is
  'The range exactly as printed on the lab report. The UI shows this with the label "as printed on your report" (src/lib/i18n.tsx "common.perReport"), and the architecture requires the lab''s own printed range to win over generic values.';
comment on column public.test_results.original_value is
  'Never overwritten. A correction writes corrected_value, so the OCR reading stays provable — this is what stops a later edit (human or AI) from erasing provenance.';
comment on column public.test_results.field_confidence is
  'Per-field OCR confidence. Free-form by nature; the scalar ocr_confidence above is the queryable rollup.';

-- One measurement of a given test per report: prevents duplicate test results.
create unique index if not exists tr_one_per_test_per_report
  on public.test_results (report_id, lab_test_id)
  where lab_test_id is not null;

-- Unmapped rows are still unique per raw label.
create unique index if not exists tr_one_per_raw_name
  on public.test_results (report_id, lower(raw_name))
  where lab_test_id is null;

-- Trend queries: all values of one test for one patient across time.
create index if not exists tr_trend_idx
  on public.test_results (lab_test_id, report_id);

create index if not exists tr_report_order_idx on public.test_results (report_id, sort_index);
create index if not exists tr_low_confidence_idx on public.test_results (report_id)
  where ocr_confidence is not null and ocr_confidence < 0.85;
create index if not exists tr_corrected_idx on public.test_results (corrected_at desc)
  where corrected_value is not null;
create index if not exists tr_range_idx on public.test_results (reference_range_id)
  where reference_range_id is not null;

drop trigger if exists tr_set_updated_at on public.test_results;
create trigger tr_set_updated_at
  before update on public.test_results
  for each row execute function public.set_updated_at();

-- Block direct mutation of the provenance fields. Corrections must go through
-- anvaya.submit_value_correction(), which writes the audit columns and an
-- audit_logs row in one transaction.
create or replace function public.guard_test_result_provenance()
returns trigger
language plpgsql
as $$
begin
  if new.report_id      is distinct from old.report_id
  or new.lab_test_id    is distinct from old.lab_test_id
  or new.raw_name       is distinct from old.raw_name
  or new.raw_value_text is distinct from old.raw_value_text
  or new.original_value is distinct from old.original_value
  or new.created_at     is distinct from old.created_at then
    raise exception 'anvaya: test_results provenance columns are immutable (report %, test %)',
      new.report_id, coalesce(new.lab_test_id::text, new.raw_name);
  end if;
  return new;
end;
$$;

comment on function public.guard_test_result_provenance() is
  'Allows legitimate updates (corrections, confidence backfill) but refuses to rewrite what the document said or when the row was created.';

drop trigger if exists tr_provenance_guard on public.test_results;
create trigger tr_provenance_guard
  before update on public.test_results
  for each row execute function public.guard_test_result_provenance();

-- ============================================================================
-- >>>> 0009_validation.sql
-- ============================================================================

-- ============================================================================
-- Anvaya / Rxanvaya — Supabase migration 0009
-- validation_results — deterministic rule-engine output (SOURCE OF TRUTH)
-- ----------------------------------------------------------------------------
-- Purpose   : The DETERMINISTIC VALIDATION stage. Low / Normal / High /
--             Borderline / Critical is decided HERE, by a versioned rule over
--             snapshotted inputs, and then frozen.
-- Depends on: 0006, 0008
-- Fresh safe: YES
-- Contract  : This is the table that satisfies the hard requirement
--             "The LLM must never be the source of truth for whether a
--             laboratory value is Low/Normal/High/Critical."
--
--             It is append-only (guard_immutable_row) and has NO write policy
--             for anon/authenticated in migration 0018 — only service_role can
--             insert. There is no UPDATE path at all, so neither a doctor edit
--             nor an LLM write-back can restate a classification. A re-run of
--             the engine creates a new row with a higher validation_seq and
--             repoints test_results.current_validation_id.
-- ============================================================================

create table if not exists public.validation_results (
  id                uuid primary key default gen_random_uuid(),
  test_result_id    uuid not null,
  validation_seq    smallint not null default 1 check (validation_seq > 0),

  -- rule that ran ------------------------------------------------------------
  rule_id           uuid not null,
  rule_version      text not null,                      -- denormalised so the verdict is readable without a join
  engine_version    text not null,

  -- inputs, snapshotted so later catalogue edits cannot rewrite history ------
  effective_value   numeric(14,5) not null,
  unit              text not null,
  range_origin      anvaya_range_origin not null,
  reference_range_id uuid,                              -- NULL when the decision used the lab-printed range
  ref_low           numeric(14,5),
  ref_high          numeric(14,5),
  critical_low      numeric(14,5),
  critical_high     numeric(14,5),
  borderline_frac   numeric(6,4) not null default 0,
  inputs_hash       text not null,                      -- sha256 over the snapshot: tamper-evidence

  -- verdict ------------------------------------------------------------------
  computed_status   anvaya_test_status not null,
  is_critical       boolean not null default false,
  is_abnormal       boolean not null default false,
  distance_from_range numeric(14,5),                    -- signed distance outside the ref bound, in `unit`
  rationale         text,                               -- human-readable trace: "7.2 > ref_high 5.7 (band 0.10) -> high"

  computed_at       timestamptz not null default now(),
  computed_by       uuid,                               -- NULL for automated runs; set for a clinician-initiated re-run

  constraint vr_fk_test_result foreign key (test_result_id) references public.test_results (id) on delete restrict,
  constraint vr_fk_rule        foreign key (rule_id)        references public.clinical_rules (id) on delete restrict,
  constraint vr_fk_range       foreign key (reference_range_id) references public.reference_ranges (id) on delete set null,
  constraint vr_fk_computed_by foreign key (computed_by)    references public.profiles (id) on delete set null,

  constraint vr_unique_seq unique (test_result_id, validation_seq),
  -- critical is a subset of abnormal
  constraint vr_critical_implies_abnormal check (not is_critical or is_abnormal),
  constraint vr_critical_matches_status check (
    is_critical = (computed_status = 'critical')
  ),
  constraint vr_range_needed_for_catalogue check (
    range_origin <> 'catalogue' or reference_range_id is not null
  ),
  -- the engine must have had at least one bound to work with
  constraint vr_needs_a_bound check (ref_low is not null or ref_high is not null)
);

comment on table public.validation_results is
  'IMMUTABLE deterministic classification. Append-only; no UPDATE, no DELETE, no client write policy. The single authoritative answer to "is this value low, normal, borderline, high or critical?"';
comment on column public.validation_results.ref_low is
  'A COPY of the bound that was in force at computed_at, not a live join. Editing reference_ranges later cannot change a past verdict — this is what makes historical reports reproducible.';
comment on column public.validation_results.inputs_hash is
  'sha256(rule_key|rule_version|engine_version|value|unit|ref_low|ref_high|critical_low|critical_high|borderline_frac). Any tampering with the snapshot is detectable.';
comment on column public.validation_results.rationale is
  'Machine-written explanation of the arithmetic. Deliberately NOT free text from a language model.';

-- Latest verdict per result: what every read path joins to.
create index if not exists vr_latest_idx
  on public.validation_results (test_result_id, validation_seq desc);
create index if not exists vr_rule_idx on public.validation_results (rule_id, computed_at desc);
create index if not exists vr_range_idx on public.validation_results (reference_range_id) where reference_range_id is not null;
create index if not exists vr_critical_idx on public.validation_results (computed_at desc) where is_critical;
create index if not exists vr_abnormal_idx on public.validation_results (computed_at desc) where is_abnormal;
create index if not exists vr_computed_at_idx on public.validation_results (computed_at desc);

drop trigger if exists vr_immutable on public.validation_results;
create trigger vr_immutable
  before update or delete on public.validation_results
  for each row execute function public.guard_immutable_row();

-- ---------------------------------------------------------------------------
-- Close the test_results <-> validation_results loop
-- ---------------------------------------------------------------------------
do $do$
begin
  if not exists (
    select 1 from pg_constraint
    where conname = 'tr_fk_current_validation'
      and conrelid = 'public.test_results'::regclass
  ) then
    alter table public.test_results
      add constraint tr_fk_current_validation
      foreign key (current_validation_id)
      references public.validation_results (id)
      on delete set null
      deferrable initially deferred;
  end if;
end
$do$;

comment on column public.test_results.current_validation_id is
  'Denormalised pointer to the newest validation_results row for this measurement. Deferred FK: the pair is written in one transaction (validation first, then repoint). It is a cache for reads — validation_results remains the source of truth.';

-- ---------------------------------------------------------------------------
-- Deterministic classification function
-- ---------------------------------------------------------------------------
create or replace function anvaya.classify_value(
  p_value           numeric,
  p_ref_low         numeric,
  p_ref_high        numeric,
  p_critical_low    numeric default null,
  p_critical_high   numeric default null,
  p_borderline_frac numeric default 0
)
returns anvaya_test_status
language sql
immutable
as $$
  with bounds as (
    select
      p_value                                                   as v,
      p_ref_low                                                 as lo,
      p_ref_high                                                as hi,
      -- reference span, used to size the borderline band. Falls back to the
      -- single available bound when the source defines an open-ended range
      -- (e.g. HbA1c "below 5.7%", where only ref_high exists).
      coalesce(p_ref_high - p_ref_low,
               p_ref_high,
               p_ref_low,
               0)                                               as span,
      p_borderline_frac                                         as bf
  )
  select case
    when b.v is null                                                  then null
    when p_critical_low  is not null and b.v < p_critical_low         then 'critical'::anvaya_test_status
    when p_critical_high is not null and b.v > p_critical_high        then 'critical'::anvaya_test_status
    when b.lo is not null and b.v < b.lo then
      case when b.bf > 0 and b.v >= b.lo - (b.span * b.bf)
           then 'borderline'::anvaya_test_status else 'low'::anvaya_test_status end
    when b.hi is not null and b.v > b.hi then
      case when b.bf > 0 and b.v <= b.hi + (b.span * b.bf)
           then 'borderline'::anvaya_test_status else 'high'::anvaya_test_status end
    else 'normal'::anvaya_test_status
  end
  from bounds b;
$$;

comment on function anvaya.classify_value(numeric, numeric, numeric, numeric, numeric, numeric) is
  'The deterministic rule. Pure, immutable, no I/O: identical inputs always yield an identical status, which is the reproducibility guarantee. Lives in the non-exposed `anvaya` schema so the browser cannot call it and fabricate a verdict.';

-- ============================================================================
-- >>>> 0010_anonymization.sql
-- ============================================================================

-- ============================================================================
-- Anvaya / Rxanvaya — Supabase migration 0010
-- anonymization_records — the PII firewall in front of every model call
-- ----------------------------------------------------------------------------
-- Purpose   : Record, per report, that de-identification happened, what was
--             stripped, and the pseudonym that was substituted. Downstream AI
--             tables reference THIS row and nothing else, which is how the
--             schema makes "identifiable patient information must not reach
--             external LLM providers" structurally true rather than a policy
--             someone has to remember.
-- Depends on: 0007
-- Fresh safe: YES
-- Contract  : NEW. Required by the ANONYMIZATION stage in
--             UPLOAD -> OCR/PARSING -> STRUCTURED TESTS -> DETERMINISTIC
--             VALIDATION -> ANONYMIZATION -> RAG -> LLM EXPLANATION -> ...
-- ============================================================================

create table if not exists public.anonymization_records (
  id              uuid primary key default gen_random_uuid(),
  lab_report_id   uuid not null,
  job_id          uuid,
  -- The token that stands in for the patient in everything sent to the model.
  -- It is a random uuid: carrying no name, no date of birth, no report number.
  pseudonym       uuid not null unique,
  method          text not null default 'direct_removal'
                  check (method in ('direct_removal', 'pseudonymisation', 'tokenisation')),
  removed_fields  jsonb not null default '[]'::jsonb,   -- ["patient_name","dob","phone","report_number","lab_name","address"]
  retained_fields jsonb not null default '[]'::jsonb,   -- ["age_band","sex","test_values","units","reference_ranges"]
  -- Age is passed as a BAND, not a value, so the payload is not re-identifiable
  -- by combining a precise DOB with other facts.
  age_band        text check (age_band is null or age_band in ('0-11','12-17','18-29','30-39','40-49','50-59','60-69','70-79','80+')),
  sex             text check (sex is null or sex in ('female', 'male', 'other', 'unspecified')),
  -- A keyed digest, NOT the data. Lets the pipeline recognise "same patient as
  -- last time" for longitudinal context without retaining identity.
  subject_digest  text,
  payload_ref     text,                                 -- storage key of the anonymised JSON, if persisted
  payload_sha256  text,
  created_by      uuid,
  created_at      timestamptz not null default now(),

  constraint anon_fk_report foreign key (lab_report_id) references public.lab_reports (id) on delete cascade,
  constraint anon_fk_job    foreign key (job_id)        references public.report_processing_jobs (id) on delete set null,
  constraint anon_fk_created_by foreign key (created_by) references public.profiles (id) on delete set null
);

comment on table public.anonymization_records is
  'The only bridge between PHI and the AI tables. Contains NO direct identifiers: no name, no phone, no email, no date of birth, no report number.';
comment on column public.anonymization_records.pseudonym is
  'This uuid is what appears in prompts and model logs. Rotating it costs nothing because nothing downstream depends on its value, only on its uniqueness per report.';
comment on column public.anonymization_records.subject_digest is
  'Keyed one-way digest. Enables "this patient has prior reports" without transmitting identity. The key lives in Vault/env, never in a table.';

create index if not exists anon_report_idx on public.anonymization_records (lab_report_id);
create index if not exists anon_job_idx on public.anonymization_records (job_id) where job_id is not null;

-- Append-only: an anonymisation assertion must not be editable after the fact.
drop trigger if exists anon_immutable on public.anonymization_records;
create trigger anon_immutable
  before update or delete on public.anonymization_records
  for each row execute function public.guard_immutable_row();

-- ============================================================================
-- >>>> 0011_rag.sql
