-- ============================================================================
-- Anvaya / Rxanvaya — Supabase migration 0016
-- Audit trail, deletion requests, persisted errors
-- ----------------------------------------------------------------------------
-- Purpose   : Append-only, hash-chained audit records; an explicit erasure
--             workflow; and durable failure records for pipeline components.
-- Depends on: 0001, 0002, 0003
-- Fresh safe: YES
-- Contract  : NEW. Nothing in the current codebase writes an audit record —
--             src/app/how/page.tsx:117-120 merely asserts "Reports can be
--             deleted after processing; data encrypted in transit and at rest."
--             These tables are what make that assertion checkable.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- audit_logs — append-only, hash-chained
-- ---------------------------------------------------------------------------
create table if not exists public.audit_logs (
  id            bigint generated always as identity primary key,
  occurred_at   timestamptz not null default now(),
  actor_id      uuid,                                   -- profiles.id; NULL for system jobs
  actor_role    anvaya_role,
  action        text not null,                          -- see the check constraint below
  entity_type   text not null,                          -- 'lab_report' | 'test_result' | 'doctor_review' | ...
  entity_id     text,                                   -- text so any PK type fits
  patient_id    uuid,                                   -- NULL-able so erasure can de-link without destroying the record
  report_id     uuid,
  outcome       text not null default 'success'
                check (outcome in ('success', 'failure', 'denied')),
  metadata      jsonb not null default '{}'::jsonb,
  ip_address    inet,
  user_agent    text,
  prev_hash     text,                                   -- row_hash of the preceding record
  row_hash      text not null,                          -- sha256 over this row + prev_hash

  -- audit rows must never carry the payload of a clinical value or a report body
  constraint audit_action_known check (action in (
    -- consent
    'consent.granted', 'consent.withdrawn', 'consent.expired', 'consent.policy_published',
    -- report lifecycle
    'report.uploaded', 'report.created', 'report.deleted', 'report.restored',
    'report.processing_started', 'report.processing_failed', 'report.processing_completed',
    -- results & determinism
    'result.extracted', 'result.corrected', 'result.validated', 'result.revalidated',
    -- privacy
    'anonymization.performed', 'pii.accessed',
    -- AI
    'ai.generation_requested', 'ai.generation_failed', 'ai.explanation_created',
    -- review & release
    'review.assigned', 'review.opened', 'review.edit_made', 'review.approved',
    'review.rejected', 'review.signed', 'report.released', 'release.revoked',
    -- access control & erasure
    'access.granted', 'access.revoked', 'access.denied', 'auth.login', 'auth.logout',
    'deletion.requested', 'deletion.completed', 'deletion.rejected', 'deletion.failed',
    -- admin
    'admin.config_changed', 'admin.reference_range_updated'
  ))
);

comment on table public.audit_logs is
  'Append-only security audit trail. Hash-chained: each row commits to the previous row''s hash, so silent deletion or editing of history is detectable. No UPDATE or DELETE path exists.';
comment on column public.audit_logs.patient_id is
  'Nullable on purpose. On erasure the link can be cleared while the FACT of the action is retained, which is how "minimal compliance information" survives without retaining PHI.';
comment on column public.audit_logs.metadata is
  'Non-sensitive context only. Never store a clinical value, a report body, or a credential here.';

create index if not exists audit_occurred_idx on public.audit_logs (occurred_at desc);
create index if not exists audit_patient_idx on public.audit_logs (patient_id, occurred_at desc) where patient_id is not null;
create index if not exists audit_report_idx on public.audit_logs (report_id, occurred_at desc) where report_id is not null;
create index if not exists audit_actor_idx on public.audit_logs (actor_id, occurred_at desc) where actor_id is not null;
create index if not exists audit_action_idx on public.audit_logs (action, occurred_at desc);
create index if not exists audit_entity_idx on public.audit_logs (entity_type, entity_id);
create index if not exists audit_denied_idx on public.audit_logs (occurred_at desc) where outcome = 'denied';

-- Hash chain + immutability --------------------------------------------------
create or replace function public.audit_seal_row()
returns trigger
language plpgsql
as $$
declare
  v_prev text;
begin
  select row_hash into v_prev from public.audit_logs order by id desc limit 1;
  new.prev_hash := v_prev;
  -- sha256() takes bytea, not text: the explicit cast is required.
  new.row_hash := encode(sha256((
    coalesce(v_prev, 'genesis') || '|' ||
    new.occurred_at::text || '|' ||
    coalesce(new.actor_id::text, '-') || '|' ||
    coalesce(new.actor_role::text, '-') || '|' ||
    new.action || '|' ||
    new.entity_type || '|' ||
    coalesce(new.entity_id, '-') || '|' ||
    coalesce(new.patient_id::text, '-') || '|' ||
    coalesce(new.report_id::text, '-') || '|' ||
    new.outcome || '|' ||
    new.metadata::text
  )::bytea), 'hex');
  return new;
end;
$$;

comment on function public.audit_seal_row() is
  'Computes prev_hash and row_hash on insert. Because audit_logs has no UPDATE/DELETE trigger allowance and no client policy, the chain can only grow.';

drop trigger if exists audit_seal on public.audit_logs;
create trigger audit_seal
  before insert on public.audit_logs
  for each row execute function public.audit_seal_row();

-- The one legitimate mutation of an audit row is DE-LINKING it from a patient
-- during erasure (see anvaya.hard_delete_patient in 0017). Everything else —
-- editing content, or any delete — is refused.
create or replace function public.guard_audit_row()
returns trigger
language plpgsql
as $$
declare
  v_erasure text;
  v_same    boolean;
begin
  if tg_op = 'DELETE' then
    raise exception 'anvaya: audit_logs is append-only; DELETE is never permitted';
  end if;

  v_erasure := current_setting('anvaya.erasure_in_progress', true);

  v_same :=
        new.occurred_at = old.occurred_at
    and new.actor_id    is not distinct from old.actor_id
    and new.actor_role  is not distinct from old.actor_role
    and new.action      = old.action
    and new.entity_type = old.entity_type
    and new.entity_id   is not distinct from old.entity_id
    and new.report_id   is not distinct from old.report_id
    and new.outcome     = old.outcome
    and new.metadata    = old.metadata
    and new.prev_hash   is not distinct from old.prev_hash
    and new.row_hash    = old.row_hash;

  if v_erasure = 'on' and v_same and old.patient_id is not null and new.patient_id is null then
    return new;   -- sanctioned de-link during erasure
  end if;

  raise exception 'anvaya: audit_logs row % is immutable', old.id;
end;
$$;

comment on function public.guard_audit_row() is
  'DELETE always refused. UPDATE refused unless the session is inside a sanctioned erasure (anvaya.erasure_in_progress = on) and the ONLY change is clearing patient_id, which de-links the record from the person while preserving the fact that the action happened.';

drop trigger if exists audit_immutable on public.audit_logs;
create trigger audit_immutable
  before update or delete on public.audit_logs
  for each row execute function public.guard_audit_row();

-- ---------------------------------------------------------------------------
-- deletion_requests — the erasure workflow
-- ---------------------------------------------------------------------------
create table if not exists public.deletion_requests (
  id            uuid primary key default gen_random_uuid(),
  patient_id    uuid not null,
  requested_by  uuid,                                   -- profiles.id (self-service or staff on behalf)
  scope         anvaya_deletion_scope not null,
  lab_report_id uuid,                                   -- set when scope = single_report
  reason        text,
  status        anvaya_deletion_status not null default 'requested',
  requested_at  timestamptz not null default now(),
  started_at    timestamptz,
  completed_at  timestamptz,
  verified_by   uuid,
  -- What was destroyed vs. what was legitimately kept.
  items_deleted jsonb not null default '{}'::jsonb,
  retained_audit boolean not null default true,
  notes         text,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),

  constraint delreq_fk_patient foreign key (patient_id) references public.patients (id) on delete cascade,
  constraint delreq_fk_report  foreign key (lab_report_id) references public.lab_reports (id) on delete set null,
  constraint delreq_fk_requested_by foreign key (requested_by) references public.profiles (id) on delete set null,
  constraint delreq_fk_verified_by foreign key (verified_by) references public.profiles (id) on delete set null,
  constraint delreq_single_needs_report check (scope <> 'single_report' or lab_report_id is not null),
  constraint delreq_completed_needs_ts check (status <> 'completed' or completed_at is not null)
);

comment on table public.deletion_requests is
  'Erasure is a workflow, not a DELETE statement. The request row survives completion and records what was destroyed, so "the patient asked and we did it" remains provable after the PHI is gone.';
comment on column public.deletion_requests.retained_audit is
  'TRUE by default: the audit_logs entries survive erasure (with patient_id cleared), because a record that a deletion happened is compliance information, not PHI.';

create index if not exists delreq_patient_idx on public.deletion_requests (patient_id, requested_at desc);
create index if not exists delreq_open_idx on public.deletion_requests (requested_at)
  where status in ('requested', 'in_progress');
create index if not exists delreq_report_idx on public.deletion_requests (lab_report_id) where lab_report_id is not null;

drop trigger if exists delreq_set_updated_at on public.deletion_requests;
create trigger delreq_set_updated_at
  before update on public.deletion_requests
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- system_errors — persisted failures
-- ---------------------------------------------------------------------------
create table if not exists public.system_errors (
  id            uuid primary key default gen_random_uuid(),
  occurred_at   timestamptz not null default now(),
  component     anvaya_component not null,
  severity      anvaya_severity not null default 'error',
  error_code    text not null,
  message       text not null,
  stack_trace   text,
  context       jsonb not null default '{}'::jsonb,     -- ANONYMISED context only
  lab_report_id uuid,
  job_id        uuid,
  generation_id uuid,
  fingerprint   text,                                   -- groups repeats of the same failure
  occurrence_count int not null default 1 check (occurrence_count > 0),
  first_seen_at timestamptz not null default now(),
  last_seen_at  timestamptz not null default now(),
  resolved_at   timestamptz,
  resolved_by   uuid,
  resolution    text,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),

  constraint err_fk_report foreign key (lab_report_id) references public.lab_reports (id) on delete set null,
  constraint err_fk_job    foreign key (job_id) references public.report_processing_jobs (id) on delete set null,
  constraint err_fk_generation foreign key (generation_id) references public.ai_generations (id) on delete set null,
  constraint err_fk_resolved_by foreign key (resolved_by) references public.profiles (id) on delete set null,
  constraint err_resolved_needs_ts check (resolved_at is null or resolution is not null),
  constraint err_window check (last_seen_at >= first_seen_at)
);

comment on table public.system_errors is
  'Durable failure records for OCR, parsing, validation, RAG and LLM stages. `context` must be anonymised — an error payload is a classic accidental PHI leak.';
comment on column public.system_errors.generation_id is
  'ON DELETE SET NULL: ai_generations is immutable, so this link is only ever dropped by an explicit administrative purge.';

create index if not exists err_recent_idx on public.system_errors (occurred_at desc);
create index if not exists err_open_idx on public.system_errors (severity, occurred_at desc) where resolved_at is null;
create index if not exists err_fingerprint_idx on public.system_errors (fingerprint, last_seen_at desc) where fingerprint is not null;
create index if not exists err_component_idx on public.system_errors (component, occurred_at desc);
create index if not exists err_report_idx on public.system_errors (lab_report_id) where lab_report_id is not null;

drop trigger if exists err_set_updated_at on public.system_errors;
create trigger err_set_updated_at
  before update on public.system_errors
  for each row execute function public.set_updated_at();

-- ============================================================================
-- >>>> 0017_functions.sql
-- ============================================================================

-- ============================================================================
-- Anvaya / Rxanvaya — Supabase migration 0017
-- Privileged functions: identity helpers, audit writer, corrections,
-- review transitions, release, erasure
-- ----------------------------------------------------------------------------
-- Purpose   : Put every state transition that must not be client-controlled
--             behind a SECURITY DEFINER function in the non-exposed `anvaya`
--             schema. The browser gets no direct write policy on any of these
--             tables; it calls a function, and the function enforces the rule
--             and writes the audit row in the same transaction.
-- Depends on: 0003-0016 (all tables)
-- Fresh safe: YES
--
-- SECURITY MODEL
--   * SECURITY DEFINER functions run as the table owner, so they can write
--     despite RLS. That is exactly why they must contain the authorisation
--     check themselves — every function below does.
--   * `set search_path` is pinned on every one of them. Without it a
--     SECURITY DEFINER function is vulnerable to search_path hijacking.
--   * None of these are added to pgrst.db_schemas, so PostgREST will not expose
--     them as RPC endpoints. The Next.js server (service role or a thin API
--     route) invokes them; the browser cannot.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- Identity helpers
-- ---------------------------------------------------------------------------
create or replace function anvaya.current_role()
returns anvaya_role
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select role from public.profiles where id = auth.uid();
$$;

comment on function anvaya.current_role() is
  'Role of the signed-in user. SECURITY DEFINER so an RLS policy can read profiles without needing a recursive policy on profiles itself.';

create or replace function anvaya.current_patient_id()
returns uuid
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select id from public.patients where profile_id = auth.uid();
$$;

create or replace function anvaya.current_doctor_id()
returns uuid
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select id from public.doctors where profile_id = auth.uid();
$$;

create or replace function anvaya.is_admin()
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select coalesce((select role = 'admin' from public.profiles where id = auth.uid()), false);
$$;

create or replace function anvaya.is_service_role()
returns boolean
language sql
stable
as $$
  select coalesce(auth.role(), '') = 'service_role';
$$;

create or replace function anvaya.is_privileged()
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select anvaya.is_service_role() or anvaya.is_admin();
$$;

comment on function anvaya.is_privileged() is
  'True for the backend service role and for admins. Used by the column guards that stop a browser session from moving a report through its lifecycle by hand.';

create or replace function anvaya.is_definer_context(p_relid oid)
returns boolean
language sql
stable
as $$
  select current_user = (
    select r.rolname
    from pg_class c
    join pg_roles r on r.oid = c.relowner
    where c.oid = p_relid
  );
$$;

comment on function anvaya.is_definer_context(oid) is
  'True when the statement is executing inside a SECURITY DEFINER function owned by the table owner (so current_user has become the owner), rather than as a direct client write. A client session is `authenticated` or `anon` and can never be the table owner, so this cannot be spoofed from the browser. Lets the sanctioned functions in this file update guarded columns while the column guards still refuse direct client writes.';

create or replace function anvaya.has_active_grant(p_doctor uuid, p_patient uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.doctor_patient_access a
    where a.doctor_id  = p_doctor
      and a.patient_id = p_patient
      and a.status     = 'active'
      and (a.expires_at is null or a.expires_at > now())
  );
$$;

comment on function anvaya.has_active_grant(uuid, uuid) is
  'The single predicate behind every doctor-facing policy: an unexpired, unrevoked grant must exist.';

create or replace function anvaya.can_access_report(p_report uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.lab_reports r
    join public.patients   p  on p.id = r.patient_id
    left join public.profiles pf on pf.id = p.profile_id
    where r.id = p_report
      and r.deleted_at is null
      and (
            pf.id = auth.uid()                                        -- owning patient
         or anvaya.is_admin()                                         -- administrator
         or exists (                                                  -- authorised clinician
              select 1
              from public.doctors d
              where d.profile_id = auth.uid()
                and anvaya.has_active_grant(d.id, p.id)
            )
      )
  );
$$;

comment on function anvaya.can_access_report(uuid) is
  'Owner, authorised reviewer, or admin — and never for a soft-deleted report. Used by the RLS policies in 0018.';

create or replace function anvaya.report_patient(p_report uuid)
returns uuid
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select patient_id from public.lab_reports where id = p_report;
$$;

create or replace function anvaya.test_result_report(p_test_result uuid)
returns uuid
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select report_id from public.test_results where id = p_test_result;
$$;

create or replace function anvaya.has_active_consent(p_patient uuid, p_purpose anvaya_consent_purpose)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  -- Append-only semantics: the MOST RECENT decision for this purpose is the one
  -- in force. A withdrawal is a newer row with status 'withdrawn', so it
  -- supersedes the earlier grant without anyone having to edit history.
  select exists (
    select 1
    from (
      select c.status, c.expires_at
      from public.patient_consents c
      where c.patient_id = p_patient
        and c.purpose    = p_purpose
      order by c.granted_at desc, c.id desc
      limit 1
    ) latest
    where latest.status = 'granted'
      and (latest.expires_at is null or latest.expires_at > now())
  );
$$;

comment on function anvaya.has_active_consent(uuid, anvaya_consent_purpose) is
  'Consent gate for the pipeline. The processing worker MUST call this before any stage that touches the model; a report whose patient has withdrawn ai_explanation consent is not eligible for generation.';

-- ---------------------------------------------------------------------------
-- Audit writer
-- ---------------------------------------------------------------------------
create or replace function anvaya.write_audit(
  p_action      text,
  p_entity_type text,
  p_entity_id   text   default null,
  p_patient_id  uuid   default null,
  p_report_id   uuid   default null,
  p_outcome     text   default 'success',
  p_metadata    jsonb  default '{}'::jsonb
)
returns bigint
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_id   bigint;
  v_ip   inet;
  v_ua   text;
begin
  begin
    v_ip := public.inet_client_addr();
  exception when others then
    v_ip := null;
  end;

  begin
    v_ua := nullif(current_setting('request.headers', true), '')::jsonb ->> 'user-agent';
  exception when others then
    v_ua := null;
  end;

  insert into public.audit_logs
    (actor_id, actor_role, action, entity_type, entity_id, patient_id, report_id, outcome, metadata, ip_address, user_agent)
  values
    (auth.uid(), anvaya.current_role(), p_action, p_entity_type, p_entity_id,
     p_patient_id, p_report_id, p_outcome, p_metadata, v_ip, v_ua)
  returning id into v_id;
  return v_id;
end;
$$;

comment on function anvaya.write_audit(text, text, text, uuid, uuid, text, jsonb) is
  'The ONLY supported way to write an audit row. The audit_seal trigger computes the hash chain; callers never touch prev_hash/row_hash.';

-- ---------------------------------------------------------------------------
-- Patient/clinician correction of a parsed value
-- ---------------------------------------------------------------------------
create or replace function anvaya.submit_value_correction(
  p_test_result_id uuid,
  p_new_value      numeric,
  p_reason         text,
  p_as_doctor      boolean default false
)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_tr       public.test_results%rowtype;
  v_report   uuid;
  v_patient  uuid;
  v_doctor   uuid;
  v_source   anvaya_value_source;
  v_new_id   uuid;
begin
  select * into v_tr from public.test_results where id = p_test_result_id for update;
  if not found then
    raise exception 'anvaya: test_result % not found', p_test_result_id;
  end if;

  v_report  := v_tr.report_id;
  v_patient := anvaya.report_patient(v_report);

  -- authorisation: the owning patient (self-correction of their own upload) or
  -- an authorised clinician. Nobody else.
  if p_as_doctor then
    v_doctor := anvaya.current_doctor_id();
    if v_doctor is null or not anvaya.has_active_grant(v_doctor, v_patient) then
      perform anvaya.write_audit('access.denied', 'test_result', p_test_result_id::text, v_patient, v_report, 'denied',
                                 jsonb_build_object('reason', 'no active grant for correction'));
      raise exception 'anvaya: not authorised to correct this result';
    end if;
    v_source := 'doctor_correction';
  else
    if anvaya.current_patient_id() is distinct from v_patient and not anvaya.is_admin() then
      perform anvaya.write_audit('access.denied', 'test_result', p_test_result_id::text, v_patient, v_report, 'denied',
                                 jsonb_build_object('reason', 'not the owning patient'));
      raise exception 'anvaya: not authorised to correct this result';
    end if;
    v_source := 'patient_correction';
  end if;

  if p_new_value is null then
    raise exception 'anvaya: a correction requires a value';
  end if;

  update public.test_results
     set corrected_value   = p_new_value,
         corrected_by      = auth.uid(),
         corrected_at      = now(),
         correction_reason = p_reason,
         value_source      = v_source
   where id = p_test_result_id;

  perform anvaya.write_audit('result.corrected', 'test_result', p_test_result_id::text, v_patient, v_report, 'success',
                             jsonb_build_object(
                               'from', v_tr.original_value,
                               'to',   p_new_value,
                               'by',   v_source));

  -- Return the CURRENT authoritative validation, so the caller can re-run the
  -- deterministic engine against the corrected value. Note what this function
  -- does NOT do: it never writes a status. Classification stays with
  -- validation_results.
  v_new_id := v_tr.current_validation_id;
  return v_new_id;
end;
$$;

comment on function anvaya.submit_value_correction(uuid, numeric, text, boolean) is
  'The only write path onto test_results correction columns. Writes the audit row in the same transaction. Deliberately does NOT set any status — the caller must re-run the deterministic engine, which appends a new validation_results row.';

-- ---------------------------------------------------------------------------
-- Review state machine
-- ---------------------------------------------------------------------------
create or replace function anvaya.set_review_status(
  p_review_id uuid,
  p_new_status anvaya_review_status,
  p_reason text default null
)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_rev     public.doctor_reviews%rowtype;
  v_doctor  uuid;
  v_patient uuid;
  v_action  text;
  v_ok      boolean;
begin
  select * into v_rev from public.doctor_reviews where id = p_review_id for update;
  if not found then
    raise exception 'anvaya: review % not found', p_review_id;
  end if;

  v_doctor  := anvaya.current_doctor_id();
  v_patient := anvaya.report_patient(v_rev.report_id);

  -- A patient must never be able to drive a review transition.
  if v_doctor is null or v_doctor <> v_rev.doctor_id then
    perform anvaya.write_audit('access.denied', 'doctor_review', p_review_id::text, v_patient, v_rev.report_id, 'denied',
                               jsonb_build_object('attempted_status', p_new_status));
    raise exception 'anvaya: only the assigned doctor may change this review';
  end if;
  if not anvaya.has_active_grant(v_doctor, v_patient) then
    raise exception 'anvaya: reviewer no longer has access to this patient';
  end if;

  -- permitted transitions
  v_ok := case
    when v_rev.status = 'draft'          and p_new_status in ('pending_review', 'withdrawn')             then true
    when v_rev.status = 'pending_review' and p_new_status in ('approved', 'needs_edit', 'withdrawn')     then true
    when v_rev.status = 'needs_edit'     and p_new_status in ('pending_review', 'withdrawn')             then true
    when v_rev.status = 'approved'       and p_new_status = 'withdrawn'                                  then true
    else false
  end;

  if not v_ok then
    raise exception 'anvaya: illegal review transition % -> %', v_rev.status, p_new_status;
  end if;

  if p_new_status = 'needs_edit' and p_reason is null then
    raise exception 'anvaya: needs_edit requires a reason';
  end if;

  update public.doctor_reviews
     set previous_status  = v_rev.status,
         status           = p_new_status,
         opened_at        = coalesce(opened_at, now()),
         decision_at      = case when p_new_status in ('approved', 'needs_edit', 'withdrawn') then now() else decision_at end,
         signed_at        = case when p_new_status = 'approved' then coalesce(signed_at, now()) else signed_at end,
         rejection_reason = case when p_new_status = 'needs_edit' then p_reason else rejection_reason end
   where id = p_review_id;

  v_action := case p_new_status
                when 'approved'     then 'review.approved'
                when 'needs_edit'   then 'review.rejected'
                when 'pending_review' then 'review.opened'
                when 'withdrawn'    then 'review.rejected'
                else 'review.opened'
              end;

  perform anvaya.write_audit(v_action, 'doctor_review', p_review_id::text, v_patient, v_rev.report_id, 'success',
                             jsonb_build_object('from', v_rev.status, 'to', p_new_status));

  update public.lab_reports
     set status = case when p_new_status = 'pending_review' then 'in_review'::anvaya_report_status else status end
   where id = v_rev.report_id and status = 'analysed';
end;
$$;

comment on function anvaya.set_review_status(uuid, anvaya_review_status, text) is
  'Enforces draft -> pending_review -> (approved | needs_edit) and refuses everything else, including any attempt by the owning patient. `released` is NOT reachable here: release is a separate, explicitly audited act (anvaya.release_report).';

-- ---------------------------------------------------------------------------
-- Release: the only path to a patient-facing report
-- ---------------------------------------------------------------------------
create or replace function anvaya.release_report(
  p_report_id  uuid,
  p_version_id uuid,
  p_review_id  uuid default null,
  p_channel    text default 'app'
)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_review  public.doctor_reviews%rowtype;
  v_patient uuid;
  v_doctor  uuid;
  v_prev    public.report_releases%rowtype;
  v_new     uuid;
begin
  select patient_id into v_patient from public.lab_reports where id = p_report_id and deleted_at is null;
  if v_patient is null then
    raise exception 'anvaya: report % not found or deleted', p_report_id;
  end if;

  if not exists (select 1 from public.report_versions where id = p_version_id and report_id = p_report_id) then
    raise exception 'anvaya: version % does not belong to report %', p_version_id, p_report_id;
  end if;

  -- the version must carry an APPROVED review by a clinician
  if p_review_id is null then
    select * into v_review
    from public.doctor_reviews
    where report_id = p_report_id and report_version_id = p_version_id and status = 'approved'
    order by decision_at desc nulls last
    limit 1;
    if not found then
      raise exception 'anvaya: no approved review exists for this report version — cannot release';
    end if;
  else
    select * into v_review from public.doctor_reviews where id = p_review_id;
    if not found or v_review.report_version_id <> p_version_id or v_review.status <> 'approved' then
      raise exception 'anvaya: review % is not an approved review of this version', p_review_id;
    end if;
  end if;

  -- only that clinician (or an admin) may release
  v_doctor := anvaya.current_doctor_id();
  if v_doctor is distinct from v_review.doctor_id and not anvaya.is_admin() then
    perform anvaya.write_audit('access.denied', 'report_release', p_report_id::text, v_patient, p_report_id, 'denied',
                               jsonb_build_object('reason', 'releaser is not the approving clinician'));
    raise exception 'anvaya: only the approving clinician may release this report';
  end if;

  -- retire any previous active release
  select * into v_prev from public.report_releases
   where report_id = p_report_id and is_active for update;
  if found then
    update public.report_releases
       set is_active = false, superseded_at = now(), superseded_by = null
     where id = v_prev.id;
  end if;

  insert into public.report_releases
    (report_id, report_version_id, review_id, released_by, release_channel)
  values
    (p_report_id, p_version_id, v_review.id, coalesce(auth.uid(), v_review.doctor_id), p_channel)
  returning id into v_new;

  update public.doctor_reviews set status = 'released' where id = v_review.id and status = 'approved';
  update public.lab_reports set status = 'released' where id = p_report_id;

  perform anvaya.write_audit('report.released', 'report_release', v_new::text, v_patient, p_report_id, 'success',
                             jsonb_build_object('version_id', p_version_id, 'review_id', v_review.id));

  return v_new;
end;
$$;

comment on function anvaya.release_report(uuid, uuid, uuid, text) is
  'The ONLY way a report becomes patient-facing. Refuses to run unless the version has an approved clinician review, and refuses to run for anyone other than that clinician. Supersedes the previous active release rather than deleting it.';

-- ---------------------------------------------------------------------------
-- Erasure
-- ---------------------------------------------------------------------------
create or replace function anvaya.hard_delete_report(
  p_report_id uuid,
  p_reason    text default null
)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_patient uuid;
begin
  select patient_id into v_patient from public.lab_reports where id = p_report_id;
  if v_patient is null then
    raise exception 'anvaya: report % not found', p_report_id;
  end if;

  -- Authorisation: the owning patient, or an admin acting on a deletion request.
  if anvaya.current_patient_id() is distinct from v_patient and not anvaya.is_admin() then
    perform anvaya.write_audit('access.denied', 'lab_report', p_report_id::text, v_patient, p_report_id, 'denied',
                               jsonb_build_object('reason', 'erasure attempted by non-owner'));
    raise exception 'anvaya: not authorised to erase this report';
  end if;

  -- Audit BEFORE destruction, so the fact survives the data.
  perform anvaya.write_audit('report.deleted', 'lab_report', p_report_id::text, v_patient, p_report_id, 'success',
                             jsonb_build_object('mode', 'hard_delete', 'reason', p_reason));

  -- Open the sanctioned-erasure window for the remainder of this transaction.
  -- Without it the append-only guards would (correctly) refuse the deletes
  -- below. It is transaction-local, so it cannot outlive this call.
  perform set_config('anvaya.erasure_in_progress', 'on', true);

  -- Dependency-ordered destruction. Nothing here relies on a blind CASCADE from
  -- patients: medical rows are RESTRICT-linked precisely so this ordering is
  -- explicit and reviewable.
  delete from public.report_releases      where report_id = p_report_id;
  delete from public.doctor_reviews       where report_id = p_report_id;
  delete from public.report_versions      where report_id = p_report_id;
  delete from public.ai_explanations      where subject_report_id = p_report_id;
  delete from public.report_patterns      where report_id = p_report_id;
  delete from public.report_files         where report_id = p_report_id;
  delete from public.anonymization_records where lab_report_id = p_report_id;
  delete from public.ocr_results          where report_id = p_report_id;
  delete from public.report_processing_jobs where report_id = p_report_id;

  -- validation_results is RESTRICT-linked to test_results, so it goes first;
  -- deleting test_results then cascades to its ai_explanations and citations.
  delete from public.validation_results
   where test_result_id in (select id from public.test_results where report_id = p_report_id);
  delete from public.test_results         where report_id = p_report_id;

  delete from public.lab_reports          where id = p_report_id;

  -- Storage objects live outside the database; remove them by prefix so no
  -- orphaned PHI remains in a bucket. Same {patient_id}/{report_id}/ convention
  -- the storage policies in 0019 rely on.
  if to_regclass('storage.objects') is not null then
    delete from storage.objects
     where bucket_id in ('report-originals', 'report-processed', 'report-exports', 'voice-audio', 'consent-evidence')
       and (storage.foldername(name))[1] = v_patient::text
       and (storage.foldername(name))[2] = p_report_id::text;
  end if;
end;
$$;

comment on function anvaya.hard_delete_report(uuid, text) is
  'True erasure of one report: writes the audit record first, then destroys clinical rows in explicit dependency order and removes the storage objects. Audit rows survive (they are compliance records, not PHI).';

create or replace function anvaya.hard_delete_patient(
  p_patient_id uuid,
  p_reason     text default null
)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_report record;
begin
  if anvaya.current_patient_id() is distinct from p_patient_id and not anvaya.is_admin() then
    perform anvaya.write_audit('access.denied', 'patients', p_patient_id::text, p_patient_id, null, 'denied',
                               jsonb_build_object('reason', 'account erasure attempted by non-owner'));
    raise exception 'anvaya: not authorised to erase this account';
  end if;

  perform set_config('anvaya.erasure_in_progress', 'on', true);

  for v_report in select id from public.lab_reports where patient_id = p_patient_id
  loop
    perform anvaya.hard_delete_report(v_report.id, p_reason);
  end loop;

  delete from public.voice_sessions    where patient_id = p_patient_id;
  delete from public.answer_feedback   where patient_id = p_patient_id;
  delete from public.patient_consents  where patient_id = p_patient_id;
  delete from public.doctor_patient_access where patient_id = p_patient_id;

  -- De-link (do not delete) the audit history: the fact that actions occurred is
  -- compliance information; the identity attached to them is not.
  update public.audit_logs set patient_id = null where patient_id = p_patient_id;

  delete from public.patients where id = p_patient_id;

  -- Written last, with no patient identifier attached, so the record that an
  -- erasure happened survives without re-identifying the person.
  perform anvaya.write_audit('deletion.completed', 'patients', null, null, null, 'success',
                             jsonb_build_object('mode', 'account_erasure', 'reason', p_reason));

  perform set_config('anvaya.erasure_in_progress', 'off', true);
end;
$$;

comment on function anvaya.hard_delete_patient(uuid, text) is
  'Account erasure. Destroys clinical data and consents, de-links the audit trail rather than deleting it, and removes the patient row. Retains exactly the minimal compliance record.';

-- ============================================================================
-- >>>> 0018_rls.sql
-- ============================================================================

-- ============================================================================
-- Anvaya / Rxanvaya — Supabase migration 0018
-- Row Level Security
-- ----------------------------------------------------------------------------
-- Purpose   : Deny-by-default access control for every table, expressed as
--             policies for the three Supabase roles (anon, authenticated,
--             service_role) plus the two application roles (patient, doctor)
--             carried in profiles.role.
-- Depends on: 0003-0017
-- Fresh safe: YES (drop policy if exists before every create)
--
-- DESIGN RULES
--   1. RLS is enabled on EVERY table. A table with no policy is unreadable,
--      which is the safe failure mode.
--   2. There is no policy at all on: validation_results (write), audit_logs
--      (insert), doctor_reviews (write), report_versions (write),
--      report_releases (write), anonymization_records, system_errors. Those
--      writes happen only through the SECURITY DEFINER functions in 0017 or
--      through the service role. "No policy" therefore means "the frontend
--      cannot do this", which is the point.
--   3. anon gets NOTHING. Every table requires an authenticated session; even
--      the non-PHI reference catalogues are gated behind sign-in so that no
--      clinical vocabulary is enumerable anonymously.
--   4. service_role bypasses RLS entirely in Supabase. The service key must
--      never be shipped to the browser — only used from Next.js route handlers.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- Enable RLS everywhere
-- ---------------------------------------------------------------------------
do $do$
declare
  r record;
begin
  for r in
    select c.relname
    from pg_class c
    join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public'
      and c.relkind = 'r'
      and not c.relrowsecurity
  loop
    execute format('alter table public.%I enable row level security', r.relname);
  end loop;
end
$do$;

-- ---------------------------------------------------------------------------
-- Column guards: RLS is row-level, so privilege escalation through a column
-- needs its own defence.
-- ---------------------------------------------------------------------------
create or replace function public.guard_profile_privileges()
returns trigger
language plpgsql
as $$
begin
  if not (anvaya.is_definer_context(tg_relid) or anvaya.is_privileged()) then
    if new.role   is distinct from old.role
    or new.status is distinct from old.status then
      raise exception 'anvaya: role and account status can only be changed by an administrator';
    end if;
    if new.id is distinct from old.id then
      raise exception 'anvaya: profile id is immutable';
    end if;
  end if;
  return new;
end;
$$;

drop trigger if exists profiles_privilege_guard on public.profiles;
create trigger profiles_privilege_guard
  before update on public.profiles
  for each row execute function public.guard_profile_privileges();

create or replace function public.guard_lab_report_core()
returns trigger
language plpgsql
as $$
begin
  -- Ownership and existence are never a client decision, in any context.
  if new.patient_id is distinct from old.patient_id then
    raise exception 'anvaya: a report cannot be reassigned to another patient';
  end if;
  if new.created_at is distinct from old.created_at then
    raise exception 'anvaya: created_at is immutable';
  end if;
  -- The pipeline/review functions run as the table owner; a browser session
  -- runs as `authenticated` and is refused.
  if not (anvaya.is_definer_context(tg_relid) or anvaya.is_privileged()) then
    if new.deleted_at is distinct from old.deleted_at then
      raise exception 'anvaya: erasure only happens through anvaya.hard_delete_report()';
    end if;
    if new.status is distinct from old.status then
      raise exception 'anvaya: report status is driven by the processing pipeline, not by the client';
    end if;
  end if;
  return new;
end;
$$;

drop trigger if exists reports_core_guard on public.lab_reports;
create trigger reports_core_guard
  before update on public.lab_reports
  for each row execute function public.guard_lab_report_core();

create or replace function public.guard_patient_identity()
returns trigger
language plpgsql
as $$
begin
  if not (anvaya.is_definer_context(tg_relid) or anvaya.is_privileged())
     and new.profile_id is distinct from old.profile_id then
    raise exception 'anvaya: patient <-> profile linkage can only be set by an administrator';
  end if;
  if new.id is distinct from old.id then
    raise exception 'anvaya: patient id is immutable';
  end if;
  return new;
end;
$$;

drop trigger if exists patients_identity_guard on public.patients;
create trigger patients_identity_guard
  before update on public.patients
  for each row execute function public.guard_patient_identity();

-- A doctor row must always belong to the caller unless privileged.
create or replace function public.guard_doctor_identity()
returns trigger
language plpgsql
as $$
begin
  if not (anvaya.is_definer_context(tg_relid) or anvaya.is_privileged())
     and new.profile_id is distinct from old.profile_id then
    raise exception 'anvaya: doctor <-> profile linkage can only be set by an administrator';
  end if;
  return new;
end;
$$;

drop trigger if exists doctors_identity_guard on public.doctors;
create trigger doctors_identity_guard
  before update on public.doctors
  for each row execute function public.guard_doctor_identity();

-- ---------------------------------------------------------------------------
-- Grants
-- ---------------------------------------------------------------------------
grant usage on schema public to anon, authenticated, service_role;
grant usage on schema anvaya to service_role;

do $do$
declare
  r record;
begin
  for r in
    select c.relname
    from pg_class c
    join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public' and c.relkind = 'r'
  loop
    execute format('grant select on public.%I to authenticated', r.relname);
    execute format('grant all on public.%I to service_role', r.relname);
  end loop;
end
$do$;

-- INSERT is granted where a patient legitimately creates their own rows; RLS
-- WITH CHECK then restricts which rows. Everything else stays service-only.
grant insert on public.patients            to authenticated;
grant update on public.patients            to authenticated;
grant insert on public.lab_reports         to authenticated;
grant update on public.lab_reports         to authenticated;
grant insert on public.report_files        to authenticated;
grant insert on public.patient_consents    to authenticated;
grant insert on public.voice_sessions      to authenticated;
grant update on public.voice_sessions      to authenticated;
grant insert on public.qa_messages         to authenticated;
grant insert, delete on public.answer_feedback to authenticated;
grant insert, update on public.deletion_requests to authenticated;
grant select on public.audit_logs          to service_role;

-- audit_logs uses an identity column; the service role needs sequence usage.
grant usage on all sequences in schema public to service_role;

-- ---------------------------------------------------------------------------
-- Function privileges
-- ---------------------------------------------------------------------------
-- `authenticated` needs USAGE on the anvaya schema so a qualified call can be
-- resolved. (RLS policies did not need it: a policy expression stores already
-- resolved function OIDs, so no name lookup happens at execution time. Any
-- direct call does require it.)
grant usage on schema anvaya to authenticated;

-- Read-only helpers MUST stay executable by `authenticated`, because RLS
-- policies invoke them as the querying user.
--
-- The five user-initiated state changes also stay executable by `authenticated`
-- ON PURPOSE: each one authorises against auth.uid() internally, so the real
-- caller's identity is what is checked. Call them from a Next.js route handler
-- using a user-scoped Supabase client built from the request's access token —
-- never with the service key.
--
-- The two functions below are pipeline-internal and are NOT callable by a
-- client session, which closes two holes at the privilege layer as well as by
-- design:
--   * anvaya.write_audit      — a client cannot forge an audit entry
--   * anvaya.classify_value   — a client cannot compute/claim a verdict
-- Both remain callable by the SECURITY DEFINER functions and by service_role,
-- which run as the table/function owner.
revoke execute on function anvaya.write_audit(text, text, text, uuid, uuid, text, jsonb)
  from public, anon, authenticated;
revoke execute on function anvaya.classify_value(numeric, numeric, numeric, numeric, numeric, numeric)
  from public, anon, authenticated;
grant execute on function anvaya.write_audit(text, text, text, uuid, uuid, text, jsonb)
  to service_role;
grant execute on function anvaya.classify_value(numeric, numeric, numeric, numeric, numeric, numeric)
  to service_role;

-- `anon` needs none of them.
revoke execute on all functions in schema anvaya from anon;
revoke execute on all functions in schema public from anon;

comment on schema anvaya is
  'Privileged helpers. Not in pgrst.db_schemas, so PostgREST exposes none of them as RPC endpoints. Read-only helpers stay executable by `authenticated` because RLS policies call them; state-changing ones authorise against auth.uid().';


-- ===========================================================================
-- POLICIES
-- ===========================================================================

-- ------------------------------- profiles ----------------------------------
drop policy if exists profiles_select_own on public.profiles;
create policy profiles_select_own on public.profiles
  for select to authenticated
  using (id = auth.uid() or anvaya.is_admin());

drop policy if exists profiles_update_own on public.profiles;
create policy profiles_update_own on public.profiles
  for update to authenticated
  using (id = auth.uid() or anvaya.is_admin())
  with check (id = auth.uid() or anvaya.is_admin());

-- No INSERT policy: rows are created by handle_new_auth_user() (SECURITY DEFINER).
-- No DELETE policy: accounts are closed, not deleted.

-- ------------------------------- patients ----------------------------------
drop policy if exists patients_select on public.patients;
create policy patients_select on public.patients
  for select to authenticated
  using (
    profile_id = auth.uid()
    or anvaya.is_admin()
    or exists (
      select 1 from public.doctors d
      where d.profile_id = auth.uid()
        and anvaya.has_active_grant(d.id, patients.id)
    )
  );

drop policy if exists patients_insert_own on public.patients;
create policy patients_insert_own on public.patients
  for insert to authenticated
